import{_ as i,o as a,c as o,a3 as t}from"./chunks/framework.vDgOMd_y.js";const m=JSON.parse('{"title":"Changelog","description":"","frontmatter":{"outline":2},"headers":[],"relativePath":"en/release-notes/changelog.md","filePath":"en/release-notes/changelog.md"}'),s={name:"en/release-notes/changelog.md"};function l(n,e,r,d,h,c){return a(),o("div",null,[...e[0]||(e[0]=[t('<div style="display:none;" hidden="true" aria-hidden="true" data-nosnippet>Are you an LLM? You can read better optimized documentation at /kimiteam/docs/en/release-notes/changelog.md for this page in Markdown format</div><h1 id="changelog" tabindex="-1">Changelog <a class="header-anchor" href="#changelog" aria-label="Permalink to &quot;Changelog&quot;">​</a></h1><p>This page documents the changes in each Kimi Code CLI release.</p><h2 id="_0-33-0-2026-08-05" tabindex="-1">0.33.0 (2026-08-05) <a class="header-anchor" href="#_0-33-0-2026-08-05" aria-label="Permalink to &quot;0.33.0 (2026-08-05)&quot;">​</a></h2><h3 id="features" tabindex="-1">Features <a class="header-anchor" href="#features" aria-label="Permalink to &quot;Features&quot;">​</a></h3><ul><li>Add Kimi Computer Use and Kimi WebBridge as built-in official marketplace entries in the v2 CLI. Installing from <code>/plugins</code> sets up the latest managed runtime and plugin together, reports incomplete manual steps, and supports retrying interrupted setup.</li><li>web: Add and manage custom providers in settings.</li><li>web: Pin sessions to the top of the sidebar.</li><li>web: Set an emoji for the session title.</li><li>web: Show the signed-in account and plan usage.</li><li>Add /bug as an alias for the /feedback slash command. Type /bug to submit feedback.</li></ul><h3 id="polish" tabindex="-1">Polish <a class="header-anchor" href="#polish" aria-label="Permalink to &quot;Polish&quot;">​</a></h3><ul><li>Ask whether to trust the current folder on startup.</li><li><code>/fork</code> no longer switches to the forked session: the current session stays active and its background tasks keep running. Find the fork in <code>/sessions</code>.</li><li>web: Overhaul the UI/UX and fix known issues.</li><li>Start the interactive TUI without creating a session.</li><li>Rename the partner plugin marketplace tab to Curated and clarify that it contains third-party plugins from Kimi partners.</li></ul><h3 id="bug-fixes" tabindex="-1">Bug Fixes <a class="header-anchor" href="#bug-fixes" aria-label="Permalink to &quot;Bug Fixes&quot;">​</a></h3><ul><li>Fix all tool calls failing with spawn EBADF on macOS when a skill folder contains a very large file tree.</li><li>Fix MCP OAuth re-authorization always failing with &quot;Invalid redirect URI&quot;; the stale client registration is now dropped and re-created with the current callback URI.</li><li>Ensure the first request waits for MCP startup to finish while the interface still opens immediately.</li><li>MCP tool results now surface the spec-defined <code>structuredContent</code> field and <code>_meta</code> server metadata to the model instead of silently dropping them, so servers that return their machine-readable contract in these fields work the same as on other MCP hosts.</li><li>Fix built-in capability availability and installed status in <code>/plugins</code>, preserve legacy WebBridge skills as backups during updates, and prevent Computer Use updates from duplicating or disconnecting MCP servers.</li></ul><h3 id="refactors" tabindex="-1">Refactors <a class="header-anchor" href="#refactors" aria-label="Permalink to &quot;Refactors&quot;">​</a></h3><ul><li>Run the CLI surfaces (interactive TUI, <code>kimi -p</code>, <code>kimi acp</code>, <code>kimi export</code>, <code>kimi provider</code>) on the agent-core-v2 engine by default. Set <code>KIMI_CODE_LEGACY_FLAG=1</code> to fall back to the legacy engine.</li></ul><h2 id="_0-32-0-2026-08-04" tabindex="-1">0.32.0 (2026-08-04) <a class="header-anchor" href="#_0-32-0-2026-08-04" aria-label="Permalink to &quot;0.32.0 (2026-08-04)&quot;">​</a></h2><h3 id="features-1" tabindex="-1">Features <a class="header-anchor" href="#features-1" aria-label="Permalink to &quot;Features&quot;">​</a></h3><ul><li>Add four hook events: <code>TurnStarted</code>, <code>UserPromptQueued</code>, <code>TaskStarted</code>, and <code>SessionHeartbeat</code>. Configure them under <code>[[hooks]]</code> in <code>config.toml</code> — see <a href="https://moonshotai.github.io/kimi-code/en/customization/hooks.html" target="_blank" rel="noreferrer">Hooks</a> for details.</li></ul><h3 id="polish-1" tabindex="-1">Polish <a class="header-anchor" href="#polish-1" aria-label="Permalink to &quot;Polish&quot;">​</a></h3><ul><li>Rename two <code>[loop_control]</code> keys: <code>max_retries_per_step</code> → <code>max_attempts_per_step</code> and <code>max_steps_per_run</code> → <code>max_steps_per_turn</code>; the old keys stop working with a rename warning at startup — see <a href="https://moonshotai.github.io/kimi-code/en/configuration/config-files.html#loop-control" target="_blank" rel="noreferrer">loop_control</a>.</li><li>Add a <code>[token_counting]</code> config section: when a provider doesn&#39;t report token usage, switch the context-size display to local estimates — see <a href="https://moonshotai.github.io/kimi-code/en/configuration/config-files.html#token-counting" target="_blank" rel="noreferrer">token_counting</a>.</li></ul><h3 id="bug-fixes-1" tabindex="-1">Bug Fixes <a class="header-anchor" href="#bug-fixes-1" aria-label="Permalink to &quot;Bug Fixes&quot;">​</a></h3><ul><li>Fix answers to interactive question prompts being rejected when the model provider returns tool call IDs containing colons (some OpenAI-compatible gateways).</li><li>Fix automatic context compaction getting stuck retrying an oversized request until it fails.</li><li>Fall back to the built-in models.dev catalog snapshot when the public catalog is unreachable, so importing a known provider still works offline or in blocked networks.</li><li>Fix the context window limit showing as 0 when no model is configured; it now falls back to the default model.</li><li>web: Fix dark-mode monochrome controls and align the chat composer corner radius with the design system.</li><li>Fix the <code>/login</code> already-logged-in confirmation being hard to read; it now uses the success color.</li></ul><h2 id="_0-31-1-2026-07-31" tabindex="-1">0.31.1 (2026-07-31) <a class="header-anchor" href="#_0-31-1-2026-07-31" aria-label="Permalink to &quot;0.31.1 (2026-07-31)&quot;">​</a></h2><h3 id="polish-2" tabindex="-1">Polish <a class="header-anchor" href="#polish-2" aria-label="Permalink to &quot;Polish&quot;">​</a></h3><ul><li>Reduce frequent full-screen redraws in the TUI.</li><li>Preserve the assistant&#39;s partial output when a turn is interrupted with Esc, and remind the model that the previous turn was deliberately interrupted.</li><li>web: Order permission modes from safest to most permissive across settings surfaces, and fix the swapped yolo/auto risk colors in the status panel and mobile settings.</li><li>web: Enable Monaco-based highlighting for code blocks, and fix line numbers overlapping or drifting out of alignment in fallback-rendered code blocks.</li></ul><h3 id="bug-fixes-2" tabindex="-1">Bug Fixes <a class="header-anchor" href="#bug-fixes-2" aria-label="Permalink to &quot;Bug Fixes&quot;">​</a></h3><ul><li>Fix sporadic &quot;model is not configured&quot; errors when starting kimi web, caused by the background provider-model refresh transiently clearing the model catalog while the first session was being created.</li><li>web: Fix new sessions showing the thinking level (e.g. Max) while the first message actually ran with thinking off.</li><li>web: Make the @ file mention work in a new-session draft, before the first prompt creates the session.</li><li>web: Fix chat code blocks rendering in the proportional UI font at the wrong size after the markdown renderer upgrade, and align the loading fallback with the highlighted block.</li></ul><h2 id="_0-31-0-2026-07-30" tabindex="-1">0.31.0 (2026-07-30) <a class="header-anchor" href="#_0-31-0-2026-07-30" aria-label="Permalink to &quot;0.31.0 (2026-07-30)&quot;">​</a></h2><h3 id="features-2" tabindex="-1">Features <a class="header-anchor" href="#features-2" aria-label="Permalink to &quot;Features&quot;">​</a></h3><ul><li>Support Markdown-defined custom agents on agent-core.</li><li>Add the /secondary_model slash command to configure the secondary model used by subagents (experimental; enable it in /experiments first).</li><li>Plugins can contribute custom agents, discovered automatically and available for sub-agent delegation.</li><li>Plugins can contribute system prompt instructions through <code>systemPrompt</code> or <code>systemPromptPath</code> in <code>kimi.plugin.json</code>.</li></ul><h3 id="bug-fixes-3" tabindex="-1">Bug Fixes <a class="header-anchor" href="#bug-fixes-3" aria-label="Permalink to &quot;Bug Fixes&quot;">​</a></h3><ul><li>Remove the blocking <code>block</code>/<code>timeout</code> wait from the TaskOutput tool so checking a background task can no longer stall the conversation; it now always returns an immediate snapshot, and completion still arrives via automatic notification.</li><li>Fix sessions missing from the session picker when their cached metadata predates the archived flag.</li><li>Fix request headers not being passed correctly on some requests.</li></ul><h2 id="_0-30-0-2026-07-29" tabindex="-1">0.30.0 (2026-07-29) <a class="header-anchor" href="#_0-30-0-2026-07-29" aria-label="Permalink to &quot;0.30.0 (2026-07-29)&quot;">​</a></h2><h3 id="features-3" tabindex="-1">Features <a class="header-anchor" href="#features-3" aria-label="Permalink to &quot;Features&quot;">​</a></h3><ul><li>Add a customizable footer status line, configured via <code>[status_line]</code> in <code>tui.toml</code>.</li></ul><h3 id="polish-3" tabindex="-1">Polish <a class="header-anchor" href="#polish-3" aria-label="Permalink to &quot;Polish&quot;">​</a></h3><ul><li>Show a quota note after installing official plugins that bill against plan quota (such as Kimi Datasource).</li><li>Show a notice when an official plugin used in the session has an update available — run /plugins to update.</li><li>Remove the 50 MB size limit on file uploads to the built-in server.</li></ul><h3 id="bug-fixes-4" tabindex="-1">Bug Fixes <a class="header-anchor" href="#bug-fixes-4" aria-label="Permalink to &quot;Bug Fixes&quot;">​</a></h3><ul><li>Fail fast when account quota or balance is exhausted instead of silently retrying for ~3 minutes.</li><li>Stop the turn after repeated invalid tool calls instead of retrying indefinitely.</li><li>web: Fix garbled line numbers in code blocks.</li></ul><h2 id="_0-29-2-2026-07-27" tabindex="-1">0.29.2 (2026-07-27) <a class="header-anchor" href="#_0-29-2-2026-07-27" aria-label="Permalink to &quot;0.29.2 (2026-07-27)&quot;">​</a></h2><h3 id="bug-fixes-5" tabindex="-1">Bug Fixes <a class="header-anchor" href="#bug-fixes-5" aria-label="Permalink to &quot;Bug Fixes&quot;">​</a></h3><ul><li>Fix goal pursuit pausing when a goal turn hits the per-turn step limit (<code>loop_control.max_steps_per_turn</code>).</li><li>Fix messages sent during goal pursuit being rejected.</li><li>Fix /undo to restore conversation history, todo lists, plan mode, and task notifications consistently.</li><li>web: Fix copying selected chat text over plain HTTP overwriting the clipboard with an event placeholder.</li></ul><h2 id="_0-29-1-2026-07-24" tabindex="-1">0.29.1 (2026-07-24) <a class="header-anchor" href="#_0-29-1-2026-07-24" aria-label="Permalink to &quot;0.29.1 (2026-07-24)&quot;">​</a></h2><h3 id="features-4" tabindex="-1">Features <a class="header-anchor" href="#features-4" aria-label="Permalink to &quot;Features&quot;">​</a></h3><ul><li>Add global default MCP server timeouts in <code>config.toml</code> and env vars.</li><li>Add environment variables to configure the web search and web fetch services without OAuth login.</li><li>Add experimental secondary-model bindings for newly spawned subagents, including per-agent model preferences and subagent-only model overrides.</li></ul><h3 id="bug-fixes-6" tabindex="-1">Bug Fixes <a class="header-anchor" href="#bug-fixes-6" aria-label="Permalink to &quot;Bug Fixes&quot;">​</a></h3><ul><li>Fix loss of thinking content with OpenAI-compatible endpoints that return reasoning under a different field name (e.g. newer vLLM).</li></ul><h2 id="_0-29-0-2026-07-22" tabindex="-1">0.29.0 (2026-07-22) <a class="header-anchor" href="#_0-29-0-2026-07-22" aria-label="Permalink to &quot;0.29.0 (2026-07-22)&quot;">​</a></h2><h3 id="features-5" tabindex="-1">Features <a class="header-anchor" href="#features-5" aria-label="Permalink to &quot;Features&quot;">​</a></h3><ul><li>web: Support defining agents in Markdown files, declaring system prompt, name, description, and tool permissions. <a href="https://moonshotai.github.io/kimi-code/en/customization/agents.html#agent-file-format" target="_blank" rel="noreferrer">Details</a></li><li>web: Permanently override the main agent&#39;s system prompt with SYSTEM.md. <a href="https://moonshotai.github.io/kimi-code/en/customization/agents.html#overriding-the-main-agent-s-system-prompt-with-system-md" target="_blank" rel="noreferrer">Details</a></li><li>web: Globally enable or disable tools across all sessions via config.toml. <a href="https://moonshotai.github.io/kimi-code/en/configuration/config-files.html#tools" target="_blank" rel="noreferrer">Details</a></li><li>Videos attached to a prompt now reach the model together with the prompt, with no extra tool round trip.</li><li>Support selecting a thinking effort level from ACP clients.</li><li>Add environment variable overrides for agent loop and background task limits.</li></ul><h3 id="polish-4" tabindex="-1">Polish <a class="header-anchor" href="#polish-4" aria-label="Permalink to &quot;Polish&quot;">​</a></h3><ul><li>Import many more providers from the models.dev catalog.</li><li>Improve TUI performance and resume speed for long-running sessions.</li><li>Reconnect a dropped MCP server connection automatically when one of its tools is called, and retry the call once.</li><li>Remove red coloring from syntax highlighting in code previews and markdown code blocks.</li><li>Add a reminder for third-party install sources to use the official installer in the update prompt.</li></ul><h3 id="bug-fixes-7" tabindex="-1">Bug Fixes <a class="header-anchor" href="#bug-fixes-7" aria-label="Permalink to &quot;Bug Fixes&quot;">​</a></h3><ul><li>Fix sessions getting stuck with a provider &quot;message must not be empty&quot; error after a content-filtered response.</li><li>Fix cancelled model requests being wrapped as retryable provider errors.</li><li>Fix thinking levels being offered for models that do not support them.</li><li>Fix config environment overrides being persisted into config.toml while the env var is set.</li><li>Send the session prompt cache key to OpenAI and OpenAI Responses providers.</li><li>Fix ReadMediaFile failing on videos when the provider has no file upload channel.</li><li>Fix goal mode continuation prompts leaking into the transcript when resuming a session.</li><li>web: Show transparent images over a checkerboard canvas.</li><li>Remove references to the non-existent <code>kimi resume</code> command from the scheduled-task tool descriptions.</li></ul><h2 id="_0-28-1-2026-07-20" tabindex="-1">0.28.1 (2026-07-20) <a class="header-anchor" href="#_0-28-1-2026-07-20" aria-label="Permalink to &quot;0.28.1 (2026-07-20)&quot;">​</a></h2><h3 id="features-6" tabindex="-1">Features <a class="header-anchor" href="#features-6" aria-label="Permalink to &quot;Features&quot;">​</a></h3><ul><li>Allow ACP sessions to start with configured non-OAuth model credentials instead of requiring terminal login.</li></ul><h3 id="polish-5" tabindex="-1">Polish <a class="header-anchor" href="#polish-5" aria-label="Permalink to &quot;Polish&quot;">​</a></h3><ul><li>Run web servers foreground-only end to end: the /web slash command now always starts a new server, and the <code>kimi web kill</code> / <code>kimi web ps</code> subcommands are removed — foreground servers stop with Ctrl+C. <code>kimi server kill</code> remains as a deprecated fallback that only stops servers started by a version before 0.28.0.</li></ul><h3 id="bug-fixes-8" tabindex="-1">Bug Fixes <a class="header-anchor" href="#bug-fixes-8" aria-label="Permalink to &quot;Bug Fixes&quot;">​</a></h3><ul><li>Fix running subagents not observing permission mode switches made after they started.</li></ul><h2 id="_0-28-0-2026-07-20" tabindex="-1">0.28.0 (2026-07-20) <a class="header-anchor" href="#_0-28-0-2026-07-20" aria-label="Permalink to &quot;0.28.0 (2026-07-20)&quot;">​</a></h2><h3 id="features-7" tabindex="-1">Features <a class="header-anchor" href="#features-7" aria-label="Permalink to &quot;Features&quot;">​</a></h3><ul><li><strong>Breaking:</strong><ul><li>The <code>kimi server</code> command tree is deprecated; use <code>kimi web</code> instead.</li><li><code>kimi web</code> now runs in the foreground of the current terminal and opens the browser; stop it with Ctrl+C.</li></ul></li></ul><h3 id="polish-6" tabindex="-1">Polish <a class="header-anchor" href="#polish-6" aria-label="Permalink to &quot;Polish&quot;">​</a></h3><ul><li>Thinking effort persists only levels below the model&#39;s top tier (max).</li><li>web: Add a note in the model switcher that switching models or thinking effort invalidates the existing prompt cache.</li></ul><h3 id="bug-fixes-9" tabindex="-1">Bug Fixes <a class="header-anchor" href="#bug-fixes-9" aria-label="Permalink to &quot;Bug Fixes&quot;">​</a></h3><ul><li>Correct the YOLO and Auto permission mode descriptions: YOLO auto-approves tool actions but the agent may still ask questions, while Auto is fully autonomous and never asks.</li><li>Fix the web backend ignoring symbolic links when loading AGENTS.md files and reading files.</li></ul><h2 id="_0-27-0-2026-07-17" tabindex="-1">0.27.0 (2026-07-17) <a class="header-anchor" href="#_0-27-0-2026-07-17" aria-label="Permalink to &quot;0.27.0 (2026-07-17)&quot;">​</a></h2><h3 id="features-8" tabindex="-1">Features <a class="header-anchor" href="#features-8" aria-label="Permalink to &quot;Features&quot;">​</a></h3><ul><li>Add the /copy slash command to copy the last assistant message to the clipboard.</li><li>Using an API key for Kimi coding models now also fetches the latest model list automatically.</li></ul><h3 id="polish-7" tabindex="-1">Polish <a class="header-anchor" href="#polish-7" aria-label="Permalink to &quot;Polish&quot;">​</a></h3><ul><li>OAuth connection errors now include the underlying network cause (DNS, refused connection, TLS, or timeout) instead of a bare &quot;fetch failed&quot;.</li></ul><h3 id="bug-fixes-10" tabindex="-1">Bug Fixes <a class="header-anchor" href="#bug-fixes-10" aria-label="Permalink to &quot;Bug Fixes&quot;">​</a></h3><ul><li>Fix repeated request rejections after an interrupted model response.</li><li>Fix the built-in URL fetch tool&#39;s network safeguards: crafted domains and redirect chains can no longer reach loopback or internal network services.</li><li>web: Fix LaTeX formulas rendering as garbled overlapping text when the web UI is accessed over the network.</li><li>web: Fix queued messages silently re-sending previously uploaded files when a session is reopened.</li><li>web: Remember the thinking level per model, fixing an empty, unresponsive thinking picker when the model doesn&#39;t support the stored level.</li><li>web: Fix duplicate workspace groups on Windows when the same folder is opened with different path spellings; its sessions now list under one merged group.</li><li>Fix AGENTS.md files installed as symbolic links being ignored by the web backend.</li><li>Fix Esc and Ctrl+C cancelling compaction instead of closing an open /btw panel.</li><li>Fix whitespace-only thinking content rendering as a blank line in the transcript.</li><li>Fix <code>/export-debug-zip</code> and <code>kimi export</code> overwriting the previous ZIP on repeated runs for the same session; the default filename now includes a timestamp.</li></ul><h2 id="_0-26-0-2026-07-16-say-hi-to-the-biiig-day" tabindex="-1">0.26.0 (2026-07-16) Say hi to the BIIIG DAY! <a class="header-anchor" href="#_0-26-0-2026-07-16-say-hi-to-the-biiig-day" aria-label="Permalink to &quot;0.26.0 (2026-07-16) Say hi to the BIIIG DAY!&quot;">​</a></h2><h3 id="polish-8" tabindex="-1">Polish <a class="header-anchor" href="#polish-8" aria-label="Permalink to &quot;Polish&quot;">​</a></h3><ul><li>Expand the coder subagent tool set to include background tasks, todo lists, plan mode, skill invocation, and nested agents, mirroring the main agent&#39;s capabilities.</li><li>Warn in the <code>/model</code> and <code>/effort</code> pickers that switching invalidates the existing prompt cache, and hint to use <code>/new</code> to avoid extra token costs.</li><li>web: Refresh the model catalog for all providers when opening the model picker, so newly available models always show up.</li><li>Optimize the unit formatting of the context usage display.</li></ul><h3 id="bug-fixes-11" tabindex="-1">Bug Fixes <a class="header-anchor" href="#bug-fixes-11" aria-label="Permalink to &quot;Bug Fixes&quot;">​</a></h3><ul><li>Fix a resumed session being marked as just updated and jumping to the top of the session list without any new activity.</li><li>Fix the context size indicator under-reporting the model&#39;s actual context usage.</li><li>Fix Kimi-provider models routed through the Anthropic protocol incorrectly showing reasoning effort options.</li><li>Honor an explicit thinking &quot;off&quot; on OpenAI-compatible (chat completions) providers.</li><li>Report when users stop tasks and preserve other stop reasons in model context.</li><li>Fix a race where resuming a background subagent right after it was manually stopped could fail with an &quot;already running&quot; error.</li><li>Replay empty thinking content verbatim instead of substituting a placeholder space on Anthropic-compatible and Kimi preserved-thinking endpoints.</li><li>Keep legacy migrations idempotent across multiple Kimi homes and report damaged or unmapped sessions instead of silently skipping them.</li><li>web: Fix the sidebar resize handle being covered by the chat composer background.</li></ul><h2 id="_0-25-0-2026-07-16" tabindex="-1">0.25.0 (2026-07-16) <a class="header-anchor" href="#_0-25-0-2026-07-16" aria-label="Permalink to &quot;0.25.0 (2026-07-16)&quot;">​</a></h2><h3 id="features-9" tabindex="-1">Features <a class="header-anchor" href="#features-9" aria-label="Permalink to &quot;Features&quot;">​</a></h3><ul><li>web: Attach any file type in chat — files can be dropped anywhere in the window, and sent files, images, and videos show as chips in the message bubble.</li></ul><h3 id="polish-9" tabindex="-1">Polish <a class="header-anchor" href="#polish-9" aria-label="Permalink to &quot;Polish&quot;">​</a></h3><ul><li>web: Show full diagnostics for model request failures.</li><li>Apply official Anthropic effort profiles and a 128k output fallback for unknown models.</li></ul><h3 id="bug-fixes-12" tabindex="-1">Bug Fixes <a class="header-anchor" href="#bug-fixes-12" aria-label="Permalink to &quot;Bug Fixes&quot;">​</a></h3><ul><li>Fix the web server bearer-token check being bypassed by percent-encoded API paths, which allowed unauthenticated access to every API route.</li><li>Fix the session filesystem API following symlinks that point outside the workspace, which allowed accessing host files beyond the session directory.</li><li>web: Keep session activity indicators in sync with agent work and prevent duplicate streamed content after session activation races or LLM retries.</li><li>Fix custom-named models on Anthropic-compatible providers starting new sessions with thinking effort off and not showing the thinking control in ACP clients.</li><li>Honor adaptive_thinking = false on Anthropic-compatible models by omitting the effort parameter from requests.</li><li>web: Fix the Content-Security-Policy on non-loopback server binds blocking the web UI&#39;s theme bootstrap script and bundled fonts.</li><li>Fix sessions failing to be created when the workspace directory is given through a symlink.</li><li>Fix the CLI exiting unexpectedly when reading an image from the clipboard fails; it now falls back to pasting text.</li><li>web: Fix completed background subagents losing their final output after a session reload.</li><li>web: Fix Enter not confirming modal confirmation dialogs in dev builds.</li><li>web: Fix a background subagent showing up as two identical rows in the agents dock panel during streaming.</li><li>Fix the diagnostic log missing the actual error when the CLI exits unexpectedly.</li></ul><h2 id="_0-24-2-2026-07-15" tabindex="-1">0.24.2 (2026-07-15) <a class="header-anchor" href="#_0-24-2-2026-07-15" aria-label="Permalink to &quot;0.24.2 (2026-07-15)&quot;">​</a></h2><h3 id="features-10" tabindex="-1">Features <a class="header-anchor" href="#features-10" aria-label="Permalink to &quot;Features&quot;">​</a></h3><ul><li>Add a builtin <code>/check-kimi-code-docs</code> skill that automatically answers Kimi Code product questions with official-docs sources.</li></ul><h3 id="polish-10" tabindex="-1">Polish <a class="header-anchor" href="#polish-10" aria-label="Permalink to &quot;Polish&quot;">​</a></h3><ul><li>Align <code>kimi -p</code> behavior across engines: <code>print_background_mode</code> and <code>print_max_turns</code> now apply, and <code>/goal</code> runs stay alive until the goal finishes.</li><li><code>kimi -p</code> now stays alive by default while background tasks are pending, with no effective wait or turn limit, and feeds each completion back to the agent. Set <code>print_background_mode = &quot;exit&quot;</code> or <code>&quot;drain&quot;</code> to restore the old exit-after-one-turn behavior.</li><li><code>kimi -p</code> background tasks and subagents no longer time out by default (interactive mode is unchanged); restore limits with <code>[background] bash_task_timeout_s</code> or <code>[subagent] timeout_ms</code>.</li><li>Subagent timeout now defaults to 2 hours everywhere; override with <code>[subagent] timeout_ms</code> or <code>KIMI_SUBAGENT_TIMEOUT_MS</code>.</li><li>The per-step LLM retry limit is raised from 3 to 10 attempts, so transient provider failures (429 / overload) are retried before a turn fails; tune with <code>loop_control.max_retries_per_step</code>.</li><li>Workspaces now stay in sync: new sessions register automatically, missing workspaces are restored at startup, and removed ones stay removed.</li><li><code>kimi web</code> now logs failed requests and key operations so daemon issues are easier to diagnose.</li><li>web: AgentSwarm cards now stay expanded while subagents are still running.</li><li>web: Minimized plan review and question cards now use an upward chevron for expand.</li></ul><h3 id="bug-fixes-13" tabindex="-1">Bug Fixes <a class="header-anchor" href="#bug-fixes-13" aria-label="Permalink to &quot;Bug Fixes&quot;">​</a></h3><ul><li>web: Fix mobile layout on iOS, including the composer, safe areas, and toasts.</li><li>Fix new sessions not opening in older CLI versions.</li><li>Fix completion notifications firing early when a subagent finished while the main turn was still running.</li><li>Fix the web UI showing the wrong CLI version.</li><li>Fix Gemini tool call IDs colliding across turns and merging swarm runs into one card.</li><li>web: Show server error details when actions like stopping or archiving a session fail.</li><li>web: Fix long responses stalling after the tab was backgrounded.</li><li>web: Fix code block copy buttons over plain HTTP.</li><li>web: Keep loaded sessions visible when the session list fails to reload.</li><li>web: Restore the AgentSwarm member list after a page refresh.</li><li>web: Fix session titles not generating when the first message is a slash command.</li><li>web: Show each message&#39;s actual send time after reloading a session.</li><li>Fix several goal-mode issues around budgets and turn limits, pausing and resuming, crash recovery, final status messages, and invalid persisted goal records.</li><li>Fix replaced goals being able to affect the new goal&#39;s budget, and reject subagent goals consistently.</li><li>Correct the guidance shown when a goal cannot be paused or resumed.</li></ul><h3 id="refactors-1" tabindex="-1">Refactors <a class="header-anchor" href="#refactors-1" aria-label="Permalink to &quot;Refactors&quot;">​</a></h3><ul><li>Rename the dynamic tool loading capability from <code>select_tools</code> to <code>dynamically_loaded_tools</code>; behavior is unchanged.</li></ul><h2 id="_0-24-1-2026-07-14" tabindex="-1">0.24.1 (2026-07-14) <a class="header-anchor" href="#_0-24-1-2026-07-14" aria-label="Permalink to &quot;0.24.1 (2026-07-14)&quot;">​</a></h2><h3 id="bug-fixes-14" tabindex="-1">Bug Fixes <a class="header-anchor" href="#bug-fixes-14" aria-label="Permalink to &quot;Bug Fixes&quot;">​</a></h3><ul><li>Fix Kimi sessions getting stuck when preserved-thinking history contains an empty reasoning step.</li><li>Fix built-in tools being unavailable when the model provider becomes ready after the session starts.</li><li>Fix Thinking effort routing: non-Kimi providers now preserve configured values, while Kimi models validate runtime selections and fall back safely during model resolution.</li><li>web: Align thinking-level handling with the CLI: submit the selected level verbatim instead of silently downgrading it, fall back to the model&#39;s own default when nothing was chosen or the model switches, and persist explicit picks as the default for new sessions.</li><li>Preserve goal completion summaries and show untyped LLM errors without an internal error-code prefix in step interruption events.</li></ul><h3 id="polish-11" tabindex="-1">Polish <a class="header-anchor" href="#polish-11" aria-label="Permalink to &quot;Polish&quot;">​</a></h3><ul><li>web: Show just the level name (e.g. Max) in the model pill instead of &quot;thinking: max&quot;.</li></ul><h2 id="_0-24-0-2026-07-14" tabindex="-1">0.24.0 (2026-07-14) <a class="header-anchor" href="#_0-24-0-2026-07-14" aria-label="Permalink to &quot;0.24.0 (2026-07-14)&quot;">​</a></h2><h3 id="features-11" tabindex="-1">Features <a class="header-anchor" href="#features-11" aria-label="Permalink to &quot;Features&quot;">​</a></h3><ul><li>web: Add session export: run <code>/export</code> or pick Export session from a session&#39;s more menu to download the session and troubleshooting logs as a ZIP (limited to 64 MiB).</li><li>Move foreground Bash commands that hit their timeout to the background instead of killing them, so long-running commands survive the timeout and report back on completion. Set <code>bash_auto_background_on_timeout = false</code> under <code>[background]</code> in config.toml to restore the kill-on-timeout behavior.</li></ul><h3 id="polish-12" tabindex="-1">Polish <a class="header-anchor" href="#polish-12" aria-label="Permalink to &quot;Polish&quot;">​</a></h3><ul><li>web: Refine goal mode controls with animated strip interactions, budget-aware progress, and design-system cancellation confirmation.</li><li>On session close, background tasks are now asked to stop and given a grace period before being force-stopped.</li><li>Rewrite repeated-tool-call reminders to redirect the agent toward a different action instead of prohibiting the call.</li><li>Optimize the TaskOutput tool prompts to discourage blocking waits on background tasks.</li><li>Send the kimi-code-cli User-Agent on provider registry (api.json) and model catalog fetches, so registries can identify the client version.</li><li>Log a warning when a skill fails to parse instead of silently dropping it, and fix skill scan results not being reported.</li></ul><h3 id="bug-fixes-15" tabindex="-1">Bug Fixes <a class="header-anchor" href="#bug-fixes-15" aria-label="Permalink to &quot;Bug Fixes&quot;">​</a></h3><ul><li>Prevent oversized image reads from poisoning sessions; sessions that already failed with request-too-large errors now recover automatically.</li><li>Fix session fork losing everything except the conversation log: forked sessions now carry over media attachments, plan files, background task output, and cron tasks, and a failed fork no longer leaves a broken copy behind.</li><li>web: Fix several session rendering glitches when reopening, reconnecting, or resyncing a session, including the context usage indicator dropping to 0, duplicate user message bubbles, and duplicated text in multi-step turns.</li><li>web: Fix uploaded images failing to display when connecting to the server over a non-localhost address.</li><li>web: Continue blocked goals after the user resumes them from the goal controls.</li><li>web: Fix the AgentSwarm member list disappearing after a page refresh while subagents are still running.</li><li>web: Fix the goal card disappearing after a page refresh while a session goal is active.</li><li>web: Fix the workspace picker menu sizing too narrowly for its content.</li><li>web: Recover transient subagent rate limits without surfacing them as session errors.</li><li>Fix Bash auto-detection on Windows failing when git comes from a native MSYS2 toolchain (ucrt64/clang64/clangarm64).</li><li>Fix OAuth login hanging after browser authorization when the provider configuration changes during sign-in.</li><li>Show the provider&#39;s actual rejection message instead of a misleading re-login prompt when an OAuth-managed model keeps returning 401 after a token refresh.</li><li>Fix providers without a configured <code>base_url</code> being rejected: anthropic/openai and other protocol providers now fall back to their official default endpoints again.</li><li>Fix MCP tools being unavailable on the first turn after session startup.</li><li>Fix pasted media and images being dropped from <code>/skill</code> and plugin command arguments, and when steering with <code>Ctrl-S</code>.</li><li>Fix empty reasoning blocks being dropped across providers, which broke multi-step tool calls.</li><li>In auto permission mode, plan exits are now marked as auto-approved instead of user-reviewed, so the agent no longer mistakes the approval for a user signal to start executing.</li><li>Fix background tasks being lost or wrongly marked as lost when resuming sessions.</li><li>Fix server shutdown sometimes leaving a stale instance file behind.</li></ul><h3 id="refactors-2" tabindex="-1">Refactors <a class="header-anchor" href="#refactors-2" aria-label="Permalink to &quot;Refactors&quot;">​</a></h3><ul><li><code>kimi web</code> now runs on the reworked agent engine by default.</li></ul><h2 id="_0-23-6-2026-07-12" tabindex="-1">0.23.6 (2026-07-12) <a class="header-anchor" href="#_0-23-6-2026-07-12" aria-label="Permalink to &quot;0.23.6 (2026-07-12)&quot;">​</a></h2><h3 id="polish-13" tabindex="-1">Polish <a class="header-anchor" href="#polish-13" aria-label="Permalink to &quot;Polish&quot;">​</a></h3><ul><li>web: Let wide Markdown tables grow beyond the reading column up to 1040px, scrolling horizontally inside the table when wider.</li><li>web: Keep the server access token for up to 7 days across tab close and browser restarts, instead of asking for it again with every new tab.</li><li>web: Add workspaces by typing an absolute path directly in the workspace picker&#39;s search box, with live validation and completion suggestions.</li><li>web: Auto-enable the default thinking effort when switching to a model that supports effort levels in the web UI.</li><li>Recognize the <code>support_efforts</code> and <code>default_effort</code> fields when importing a custom registry, so thinking effort levels are available for those models.</li><li>Update the WebBridge install page link opened from the <code>/plugins</code> panel.</li><li>Add a <code>subagent.timeout_ms</code> config option (or the <code>KIMI_SUBAGENT_TIMEOUT_MS</code> env var) to control how long a single subagent may run before timing out; the default is raised from 30 minutes to 2 hours.</li><li>Add a print-mode background policy: set <code>[background].print_background_mode = &quot;steer&quot;</code> to keep <code>kimi -p</code> alive across background-task completions, so the main agent can be steered into follow-up turns.</li></ul><h3 id="bug-fixes-16" tabindex="-1">Bug Fixes <a class="header-anchor" href="#bug-fixes-16" aria-label="Permalink to &quot;Bug Fixes&quot;">​</a></h3><ul><li>web: Fix sessions getting stuck in a sending state after a reconnect; turns that finish while the connection is down now stop the spinner and let the next message send normally.</li><li>web: Fix the first visit after starting or updating the web UI bouncing to the login page when the initial auth check fails; the connecting screen now stays up, shows the connection error, and retries.</li><li>Keep <code>kimi -p</code> runs alive after a turn ends while a goal is still active or a cron task is pending, so goal continuations and cron fires run their turns instead of being cut off when the main turn finishes.</li><li>Treat a dismissed question prompt as the user choosing not to answer, instead of implicitly selecting the recommended option.</li><li>web: Fix ReadMediaFile results rendering as plain tool cards instead of images after resuming or reloading a session.</li><li>web: Fix the chat view jumping downward while scrolling through conversation history.</li><li>web: Fix the model dropdown showing checkmarks on same-named models from other providers; the current model is now matched by its unique model id.</li><li>web: Fix sidebar lag with many sessions by removing repeated session list scans during rendering.</li></ul><h3 id="refactors-3" tabindex="-1">Refactors <a class="header-anchor" href="#refactors-3" aria-label="Permalink to &quot;Refactors&quot;">​</a></h3><ul><li>Rename the dynamic tool loading model capability from <code>select_tools</code> to <code>dynamically_loaded_tools</code>.</li></ul><h2 id="_0-23-5-2026-07-10" tabindex="-1">0.23.5 (2026-07-10) <a class="header-anchor" href="#_0-23-5-2026-07-10" aria-label="Permalink to &quot;0.23.5 (2026-07-10)&quot;">​</a></h2><h3 id="polish-14" tabindex="-1">Polish <a class="header-anchor" href="#polish-14" aria-label="Permalink to &quot;Polish&quot;">​</a></h3><ul><li>Retry provider 429, overload, and other transient errors more reliably, honoring the server Retry-After delay, and surface retries in <code>-p --output-format stream-json</code>.</li></ul><h3 id="bug-fixes-17" tabindex="-1">Bug Fixes <a class="header-anchor" href="#bug-fixes-17" aria-label="Permalink to &quot;Bug Fixes&quot;">​</a></h3><ul><li>Stop unsupported image formats (AVIF, BMP, TIFF, ICO, …) from breaking sessions at every entry point — including remote image URLs and images mislabeled by a tool — and recover an already-stuck session by dropping the offending image and retrying, so one such image can no longer make every later request fail.</li><li>web: Fix the &quot;Turn finished&quot; desktop notification and completion sound firing twice per turn.</li><li>web: Hide the internal image-compression note so it no longer renders as user message text.</li></ul><h2 id="_0-23-4-2026-07-10" tabindex="-1">0.23.4 (2026-07-10) <a class="header-anchor" href="#_0-23-4-2026-07-10" aria-label="Permalink to &quot;0.23.4 (2026-07-10)&quot;">​</a></h2><h3 id="features-12" tabindex="-1">Features <a class="header-anchor" href="#features-12" aria-label="Permalink to &quot;Features&quot;">​</a></h3><ul><li>web: Add notifications when a tool needs approval, and improve notification reliability.</li></ul><h3 id="polish-15" tabindex="-1">Polish <a class="header-anchor" href="#polish-15" aria-label="Permalink to &quot;Polish&quot;">​</a></h3><ul><li>web: Polish the chat UI with Inter typography, localized labels, and tighter composer and menu styling.</li><li>web: Polish the session sidebar layout, colors, icons, and typography.</li><li>Display the Extra Usage (fuel pack) balance in the <code>/usage</code> and <code>/status</code> commands.</li><li>Add a Kimi WebBridge entry to the Official tab of the <code>/plugins</code> panel that opens the WebBridge install page in your browser.</li></ul><h3 id="bug-fixes-18" tabindex="-1">Bug Fixes <a class="header-anchor" href="#bug-fixes-18" aria-label="Permalink to &quot;Bug Fixes&quot;">​</a></h3><ul><li>Keep image-heavy sessions within provider request-size limits: oversized images (model-read and pasted, including WebP) are downscaled and compressed, HEIC/HEIF reads are refused with a platform-matched conversion command instead of poisoning the session, and an HTTP 413 request-too-large now recovers automatically — the request and <code>/compact</code> retry with older media replaced by text markers. The limits are configurable via <code>[image]</code> in <code>config.toml</code> (or <code>KIMI_IMAGE_*</code> env vars), and each core keeps its own settings so reloading one client&#39;s config no longer changes another client&#39;s compression.</li><li>Fix resuming sessions whose original working directory no longer exists.</li><li>Fix prompt-mode goals so they run until completion and report invalid goal commands before sending prompts.</li><li>web: Fix an occasional &quot;another turn is active&quot; error when sending the first message of a new conversation, and show a starting state while it is being sent.</li></ul><h2 id="_0-23-3-2026-07-08" tabindex="-1">0.23.3 (2026-07-08) <a class="header-anchor" href="#_0-23-3-2026-07-08" aria-label="Permalink to &quot;0.23.3 (2026-07-08)&quot;">​</a></h2><h3 id="bug-fixes-19" tabindex="-1">Bug Fixes <a class="header-anchor" href="#bug-fixes-19" aria-label="Permalink to &quot;Bug Fixes&quot;">​</a></h3><ul><li>Fix a misleading &quot;OAuth login expired&quot; message shown when a model is not available for the current account.</li></ul><h2 id="_0-23-2-2026-07-08" tabindex="-1">0.23.2 (2026-07-08) <a class="header-anchor" href="#_0-23-2-2026-07-08" aria-label="Permalink to &quot;0.23.2 (2026-07-08)&quot;">​</a></h2><h3 id="features-13" tabindex="-1">Features <a class="header-anchor" href="#features-13" aria-label="Permalink to &quot;Features&quot;">​</a></h3><ul><li>Add the Vercel plugin to the bundled plugin marketplace. Run <code>/plugins</code> and select Vercel Plugin to install it.</li></ul><h3 id="bug-fixes-20" tabindex="-1">Bug Fixes <a class="header-anchor" href="#bug-fixes-20" aria-label="Permalink to &quot;Bug Fixes&quot;">​</a></h3><ul><li>Fix <code>kimi -p</code> runs exiting with code 0 when a turn fails.</li><li>Prevent autonomous goals from being paused by model-reported status updates.</li><li>Count the turn that starts an autonomous goal toward its turn budget.</li><li>Raise the image downscale cap from 2000px to 3000px, and fix swapped width/height for EXIF-rotated (portrait) photos in compression captions and media read notes so region readback coordinates map correctly.</li><li>web: Fix the connection error toast lingering after the WebSocket reconnects when returning from the background.</li><li>Fix console windows flashing on Windows each time a hook runs.</li></ul><h3 id="polish-16" tabindex="-1">Polish <a class="header-anchor" href="#polish-16" aria-label="Permalink to &quot;Polish&quot;">​</a></h3><ul><li>web: Redesign the scheduled reminder UI.</li><li>web: Show session skills in the slash menu as <code>/skill:&lt;name&gt;</code> so they are distinguishable from built-in commands; typing the bare skill name still works.</li><li>web: The composer model switcher switches the active session&#39;s model as before and additionally bumps the global default model, so new sessions inherit the choice.</li><li>web: Press Enter to confirm in archive and other confirmation dialogs.</li><li>Tighten goal-mode guidance for blocked and complete status updates.</li><li>Progressive tool disclosure (<code>select_tools</code>, experimental): compaction now discards the loaded tool schemas instead of re-injecting them, and the model re-selects the tools it still needs afterward. A from-memory call to a no-longer-loaded tool is rejected with guidance to select it first. No effect unless the <code>tool-select</code> experimental flag and a <code>select_tools</code>-capable model are active.</li></ul><h3 id="refactors-4" tabindex="-1">Refactors <a class="header-anchor" href="#refactors-4" aria-label="Permalink to &quot;Refactors&quot;">​</a></h3><ul><li>web: Compile icons at build time so the bundled web UI only carries the icons it renders.</li></ul><h2 id="_0-23-1-2026-07-07" tabindex="-1">0.23.1 (2026-07-07) <a class="header-anchor" href="#_0-23-1-2026-07-07" aria-label="Permalink to &quot;0.23.1 (2026-07-07)&quot;">​</a></h2><h3 id="bug-fixes-21" tabindex="-1">Bug Fixes <a class="header-anchor" href="#bug-fixes-21" aria-label="Permalink to &quot;Bug Fixes&quot;">​</a></h3><ul><li>Fix <code>kimi -p</code> abandoning background subagents that start late or run long, so their results reach the main agent.</li><li>web: Recover chat streaming after a stale background-tab WebSocket instead of requiring a page refresh.</li><li>Fix some third-party models (e.g. Opus 4.8) falling back to the family default max output tokens; an unrecognized minor now reuses the nearest earlier known version&#39;s limit.</li><li>Honor explicit Anthropic <code>max_output_size</code> settings instead of clamping them to built-in ceilings.</li><li>Stop showing tool-produced <code>&lt;system&gt;</code> metadata in tool outputs; failed tools now show their own error text.</li><li>Fix goal completion and blocked updates to produce one final user-facing outcome summary from the tool result.</li><li>Fix goal startup and queue handling so failed starts restore permission mode and queued goals wait behind new user messages.</li><li>Fix goal token budgets to count model completion tokens and stop without extra continuation steps when the budget is exhausted.</li><li>Fix goal tools being unavailable to the main agent, and return clear messages for invalid goal-control calls.</li><li>Respect the <code>--skills-dir</code> flag in interactive mode.</li><li>web: Fix several slash commands and skills not working on the new-session screen: <code>/goal &lt;objective&gt;</code> and slash skill activations (for example <code>/pre-changelog</code>) silently did nothing, and <code>/btw [&lt;question&gt;]</code> opened an empty side chat.</li></ul><h3 id="polish-17" tabindex="-1">Polish <a class="header-anchor" href="#polish-17" aria-label="Permalink to &quot;Polish&quot;">​</a></h3><ul><li>Preserve prior turns&#39; thinking by default on the Anthropic provider (Claude and Kimi&#39;s Anthropic-compatible mode), matching the Kimi default. Disable with <code>[thinking] keep = &quot;off&quot;</code> or <code>KIMI_MODEL_THINKING_KEEP=off</code>.</li><li>Clarify the permission mode descriptions shown by <code>/permission</code>, <code>/auto</code>, and <code>/yolo</code>, and reorder <code>/auto</code> and <code>/yolo</code> in the command list.</li><li>Show long-running goal wall-clock budget reminders in hours.</li><li>Tighten goal-mode guidance so agents continue reasonable work across turns instead of ending goals prematurely.</li></ul><h3 id="refactors-5" tabindex="-1">Refactors <a class="header-anchor" href="#refactors-5" aria-label="Permalink to &quot;Refactors&quot;">​</a></h3><ul><li>Record a per-request trace in the session wire log, so model requests can be reconstructed for debugging.</li></ul><h2 id="_0-23-0-2026-07-06" tabindex="-1">0.23.0 (2026-07-06) <a class="header-anchor" href="#_0-23-0-2026-07-06" aria-label="Permalink to &quot;0.23.0 (2026-07-06)&quot;">​</a></h2><h3 id="features-14" tabindex="-1">Features <a class="header-anchor" href="#features-14" aria-label="Permalink to &quot;Features&quot;">​</a></h3><ul><li>web: Add an Archived sessions page in Settings to browse and restore archived sessions. Open Settings → Archived to find it.</li><li>Add experimental on-demand tool loading (<code>select_tools</code>) under the <code>tool-select</code> flag: a supporting model loads MCP tools only when needed instead of sending all of them in every request, preserving the provider prompt cache. Off by default and only active on models that declare the <code>select_tools</code> capability.</li></ul><h3 id="bug-fixes-22" tabindex="-1">Bug Fixes <a class="header-anchor" href="#bug-fixes-22" aria-label="Permalink to &quot;Bug Fixes&quot;">​</a></h3><ul><li>Fix sessions that exist on disk but were missing from the session list or returned 404 on direct access, by rebuilding the session index at server startup.</li><li>Fix the Bash and Edit tool cards collapsing, jumping, or flickering in height when results stream in or finish with short output, and visually separate the Bash command from its output.</li><li>Fix the input box shifting upward after the slash command menu closes.</li><li>Fix the edit approval preview shown by Ctrl+E to include surrounding context lines, matching the summary panel.</li><li>Fix <code>@</code> file completion missing deeply nested files in large projects after adding extra workspace directories.</li><li>web: Fix several web layout and animation glitches: the collapsed sidebar now hides correctly, the chat history no longer replays its entrance animation when opening a session, and tool components no longer jump the conversation when expanded or collapsed.</li><li>web: Fix scheduled-reminder (cron) fires being hidden; they now show as notice cards in the chat.</li><li>web: Fix the end of a reply staying missing after reopening a session.</li><li>web: Fix queued media messages not loading back into the composer and keep attachments when undoing a message.</li><li>web: Keep the composer toolbar from clipping its controls on narrow windows and phones, with the context ring staying visible at every width.</li><li>web: Fix the font size setting so chat text, composer text, and sidebar text follow the selected size.</li><li>web: Fix an almost-invisible composer input caret and a washed-out strikethrough on completed todos.</li><li>web: Show the correct session search shortcut on Windows.</li><li>Fix tool calling with Google Gemini models, including Gemini 3 thinking-signature round-trips across turns.</li></ul><h3 id="polish-18" tabindex="-1">Polish <a class="header-anchor" href="#polish-18" aria-label="Permalink to &quot;Polish&quot;">​</a></h3><ul><li>web: Replace the swarm footer with a single inline tool card that shows live subagent progress and the aggregated result, and keep the swarm progress bar stable after refresh.</li><li>Show compaction summaries in the TUI after compaction. Press Ctrl+O to show or hide the summary.</li><li>web: Render AskUserQuestion answers as a readable option list with the chosen option(s) highlighted, instead of raw JSON.</li><li>web: Show available skills in the composer before a session is created.</li><li>web: Add an Archived sessions entry to the mobile settings sheet and clarify the archive confirmation to mention restoring from Settings.</li><li>web: Show the Kimi icon and clearer titles in desktop notifications.</li><li>web: Align the markdown diff code block with the design system: code text keeps the normal ink colour while the sign and a soft row background carry the change, matching the <code>~/diff</code> panel.</li><li>web: Prevent chat text from hyphenating at line breaks and render code without font ligatures.</li><li>web: Drop the stray left indent in the tool-call card body so expanded content aligns with the header.</li><li>Feed AskUserQuestion answers back to the model as question text and option labels instead of positional ids, so the model no longer has to map them back. Question texts must now be unique per call and option labels unique per question; existing clients keep answering with option ids, so no client change is required.</li><li>Keep prior reasoning across turns for Kimi models by default when Thinking is on. Set <code>[thinking] keep = &quot;off&quot;</code> to disable.</li></ul><h2 id="_0-22-3-2026-07-04" tabindex="-1">0.22.3 (2026-07-04) <a class="header-anchor" href="#_0-22-3-2026-07-04" aria-label="Permalink to &quot;0.22.3 (2026-07-04)&quot;">​</a></h2><h3 id="bug-fixes-23" tabindex="-1">Bug Fixes <a class="header-anchor" href="#bug-fixes-23" aria-label="Permalink to &quot;Bug Fixes&quot;">​</a></h3><ul><li>Wait for background subagents to finish and respond to their results before exiting in <code>kimi -p</code>, instead of ending the turn early.</li><li>web: Fix uploaded videos failing to play in the web chat.</li><li>Revert the recent TUI transcript rendering changes to the original upstream behavior and fix related rendering issues.</li></ul><h3 id="polish-19" tabindex="-1">Polish <a class="header-anchor" href="#polish-19" aria-label="Permalink to &quot;Polish&quot;">​</a></h3><ul><li>Add <code>--dangerous-bypass-auth</code> and <code>--keep-alive</code> flags to <code>kimi server run</code>, so the server can run without a token on trusted networks and stay alive past the idle timeout.</li><li>web: Add click-to-enlarge for images uploaded in the web chat. Click an image in a message to open it.</li></ul><h2 id="_0-22-2-2026-07-03" tabindex="-1">0.22.2 (2026-07-03) <a class="header-anchor" href="#_0-22-2-2026-07-03" aria-label="Permalink to &quot;0.22.2 (2026-07-03)&quot;">​</a></h2><h3 id="bug-fixes-24" tabindex="-1">Bug Fixes <a class="header-anchor" href="#bug-fixes-24" aria-label="Permalink to &quot;Bug Fixes&quot;">​</a></h3><ul><li>Fix sessions silently dropping later user messages after a turn was interrupted between a tool call and its result.</li><li>Fix requests being rejected by strict providers when the model emits duplicate tool call ids.</li><li>Fix <code>kimi upgrade</code> failing on Windows with a spawn error when installing the new version.</li><li>Fix duplicated transcript content appearing in scrollback during streaming.</li><li>Fix compressed-image prompts leaking an internal <code>&lt;system&gt;</code> compression note into the visible message and the session title.</li><li>Keep automatic background updates from flashing a console window on Windows.</li></ul><h3 id="polish-20" tabindex="-1">Polish <a class="header-anchor" href="#polish-20" aria-label="Permalink to &quot;Polish&quot;">​</a></h3><ul><li>Have context-compaction notes capture a forward plan for the remaining work — upcoming steps, settled decisions, and foreseeable obstacles — instead of only the immediate next step, so the agent continues more coherently after auto-compaction.</li><li>Enrich PATH from the user&#39;s login shell at startup, so shell commands find user-installed tools (e.g. Homebrew&#39;s <code>gh</code>) even when kimi-code was launched without the full profile PATH.</li><li>Promote the language-matching rule to a dedicated section in the system prompt, so replies and reasoning consistently follow the user&#39;s language through long English tool output, while repository artifacts keep project conventions.</li><li>Add a TUI preference to keep rapid multi-line pastes from submitting line by line when bracketed paste is unavailable. Set <code>disable_paste_burst = true</code> in <code>tui.toml</code> to turn it off.</li><li>Keep subagent cards at a stable height and show a live status spinner with a compact two-row activity window.</li><li>In <code>kimi -p</code> runs, wait for background subagents to finish before exiting when <code>background.keep_alive_on_exit</code> is enabled. Set <code>keep_alive_on_exit = true</code> to let concurrent background subagents complete.</li></ul><h3 id="refactors-6" tabindex="-1">Refactors <a class="header-anchor" href="#refactors-6" aria-label="Permalink to &quot;Refactors&quot;">​</a></h3><ul><li>Record model response ids in session wire logs to make individual model requests easier to trace.</li></ul><h2 id="_0-22-1-2026-07-02" tabindex="-1">0.22.1 (2026-07-02) <a class="header-anchor" href="#_0-22-1-2026-07-02" aria-label="Permalink to &quot;0.22.1 (2026-07-02)&quot;">​</a></h2><h3 id="bug-fixes-25" tabindex="-1">Bug Fixes <a class="header-anchor" href="#bug-fixes-25" aria-label="Permalink to &quot;Bug Fixes&quot;">​</a></h3><ul><li>Fix TUI rendering bugs that caused the screen to go blank and the input box to disappear.</li><li>Fix the TUI crashing when the terminal is resized to a very narrow width while the input contains CJK or emoji text.</li><li>Fix the web UI becoming sluggish after opening many sessions.</li><li>Clear the screen fully when starting a new session via /new, /clear, or a session switch.</li><li>Fix web tooltips that could get stuck on screen when their trigger element is removed while open.</li><li>Fix the sidebar session row shifting its title and status badges when hovered.</li><li>Fix the session search dialog showing a horizontal scrollbar for long session titles or snippets.</li></ul><h3 id="polish-21" tabindex="-1">Polish <a class="header-anchor" href="#polish-21" aria-label="Permalink to &quot;Polish&quot;">​</a></h3><ul><li>Improve compaction handoff summaries for more reliable resumed sessions. They now keep the latest intent, key tool results, decisions, open questions, and context to re-check.</li><li>Save shell commands to input history and recall them in bash mode. Press Up on an empty <code>!</code> prompt to browse previous shell commands.</li><li>When large images are compressed, tell the model the original and delivered image details. Keep the original image available, and support cropped or full-resolution reads for fine details.</li><li>Refresh the web UI icon set and unify the message copy and undo button hover states and tooltips.</li><li>Let the web sidebar collapse an expanded workspace session list back to its first page.</li><li>Trim redundant and incorrect tooltips in the web UI.</li><li>Show an up arrow on the web composer send button.</li></ul><h3 id="refactors-7" tabindex="-1">Refactors <a class="header-anchor" href="#refactors-7" aria-label="Permalink to &quot;Refactors&quot;">​</a></h3><ul><li>Remove the experimental micro compaction feature and its toggle from the experiments panel.</li><li>Remove duplicate newline-shortcut handling from the prompt editor.</li></ul><h2 id="_0-22-0-2026-07-02" tabindex="-1">0.22.0 (2026-07-02) <a class="header-anchor" href="#_0-22-0-2026-07-02" aria-label="Permalink to &quot;0.22.0 (2026-07-02)&quot;">​</a></h2><h3 id="features-15" tabindex="-1">Features <a class="header-anchor" href="#features-15" aria-label="Permalink to &quot;Features&quot;">​</a></h3><ul><li>Automatically compress oversized images before they reach the model, downsampling and re-encoding them to cut vision-token cost and avoid provider image-size errors.</li><li>Add model alias overrides, letting you set model metadata under <code>[models.&quot;&lt;alias&gt;&quot;.overrides]</code> to override provider catalog refresh results.</li></ul><h3 id="bug-fixes-26" tabindex="-1">Bug Fixes <a class="header-anchor" href="#bug-fixes-26" aria-label="Permalink to &quot;Bug Fixes&quot;">​</a></h3><ul><li>Fix plan, swarm, and goal modes being shared across sessions in the web UI; each session now keeps its own toggles.</li><li>Fix the transcript jumping to the top when scrolling up through history during streaming output.</li><li>Release pasted images and streaming timers once they are no longer shown, so memory stops growing in long sessions.</li><li>Fix the terminal being left in raw mode with a hidden cursor and disabled flow control after a crash or abrupt exit.</li><li>Fix an active workspace showing only its five most recent sessions on load, so it now keeps loading older sessions from the last 12 hours.</li><li>Fix the Thinking-by-default setting not taking effect, so new sessions correctly start with thinking enabled.</li><li>Fix spurious errors from the web question, approval, and task actions when the action was already complete, and add loading feedback so each click is acknowledged immediately.</li><li>Show draft pull requests with a distinct draft status instead of displaying them as open.</li><li>Hide the conversation outline when there is not enough room to expand its labels, so it no longer clips against the window edge.</li><li>Hide the unsupported Off option in the /model thinking switcher for always-on models that already expose multiple effort levels.</li></ul><h3 id="polish-22" tabindex="-1">Polish <a class="header-anchor" href="#polish-22" aria-label="Permalink to &quot;Polish&quot;">​</a></h3><ul><li>Refresh the web UI with a new design system, including updated colors, typography, spacing, light and dark palettes, restyled tooltips, and subtle enter/exit and expand/collapse animations.</li><li>Group consecutive tool calls into a collapsible stack with per-tool renderers, including diff line-count chips for edits and inline previews for image, video, and audio results.</li><li>Improve session search with a Cmd/Ctrl+K palette that filters by title, workspace, and last prompt with highlighted matches. Press Cmd+K or Ctrl+K to open it.</li><li>Show queued prompts inline below the running turn in the web chat, and split Stop into its own button so Send no longer interrupts.</li><li>Show the conversation outline as one entry per user query that expands into a labeled list on hover.</li><li>Replace the Explore and Native theme options with a single chat layout and a Blue or Black accent-color setting.</li><li>Add workspace sorting by manual order or last-edited time, plus collapse-all and expand-all controls, to the sidebar.</li><li>Show time, duration, connection, and stack details in web error and warning toasts.</li><li>Use one consistent modal dialog for confirmations in the web UI (archive session, delete workspace, delete provider, undo message, and mode toggles).</li><li>Reduce the default TUI transcript window to keep long sessions responsive.</li><li>Reduce the web composer&#39;s default height for a more compact empty state, and fix ArrowUp recalling the previous message while editing a multi-line draft; ArrowUp now recalls only from the very start of the text and is disabled in the expanded editor.</li><li>Remove the fade-out animation when undoing a message in the web chat.</li></ul><h2 id="_0-21-1-2026-07-01" tabindex="-1">0.21.1 (2026-07-01) <a class="header-anchor" href="#_0-21-1-2026-07-01" aria-label="Permalink to &quot;0.21.1 (2026-07-01)&quot;">​</a></h2><h3 id="bug-fixes-27" tabindex="-1">Bug Fixes <a class="header-anchor" href="#bug-fixes-27" aria-label="Permalink to &quot;Bug Fixes&quot;">​</a></h3><ul><li>Keep the waiting spinner visible while encrypted reasoning streams, fixing a blank spinner-less gap before the first response text appears.</li></ul><h2 id="_0-21-0-2026-07-01" tabindex="-1">0.21.0 (2026-07-01) <a class="header-anchor" href="#_0-21-0-2026-07-01" aria-label="Permalink to &quot;0.21.0 (2026-07-01)&quot;">​</a></h2><h3 id="features-16" tabindex="-1">Features <a class="header-anchor" href="#features-16" aria-label="Permalink to &quot;Features&quot;">​</a></h3><ul><li>Plugins can now provide slash commands via a <code>commands</code> field in their manifest, registered as <code>&lt;plugin&gt;:&lt;command&gt;</code> and invoked with <code>$ARGUMENTS</code> expansion.</li><li>Add Mermaid diagram rendering to the web chat. Fenced <code>mermaid</code> blocks in assistant responses now render as diagrams. KaTeX math and Mermaid diagram parsing also run in Web Workers to keep the UI responsive during live streaming.</li></ul><h3 id="bug-fixes-28" tabindex="-1">Bug Fixes <a class="header-anchor" href="#bug-fixes-28" aria-label="Permalink to &quot;Bug Fixes&quot;">​</a></h3><ul><li>Stop a malformed message history from permanently bricking a session on strict providers (Anthropic). The request is repaired before sending — orphaned tool calls are closed and empty/whitespace-only text blocks dropped — and if the provider still rejects its structure, it is resent once with a wire-compliant rebuild.</li><li>Force-exit headless runs (<code>kimi -p</code>) so a stray ref&#39;d handle left over from the run can&#39;t keep a completed run alive until an external timeout, and bound prompt cleanup so a wedged shutdown step can&#39;t hang shutdown.</li><li>Fix @ file mentions not opening when typed inside a slash command argument.</li><li>Fix adding a workspace by path in the web UI failing silently when the daemon rejects the path; it now shows an error instead of a broken workspace.</li><li>Fix duplicate workspaces showing in the web sidebar when the same folder is registered more than once.</li><li>Fix the web workspace rename not persisting after a page refresh.</li></ul><h3 id="polish-23" tabindex="-1">Polish <a class="header-anchor" href="#polish-23" aria-label="Permalink to &quot;Polish&quot;">​</a></h3><ul><li>Add a double-Esc shortcut to open the undo selector. Press Esc twice while idle to undo.</li><li>Show file path completions when typing <code>/</code> in shell mode (<code>!</code>).</li><li>Always show the usage-data opt-out toggle in the web settings with a clearer label and description.</li></ul><h3 id="refactors-8" tabindex="-1">Refactors <a class="header-anchor" href="#refactors-8" aria-label="Permalink to &quot;Refactors&quot;">​</a></h3><ul><li>Rework conversation compaction: <ul><li>Keep only recent user prompts plus a single user-role summary; drop assistant and tool messages.</li><li>Repair tool_use/tool_result adjacency before sending, fixing a strict-provider HTTP 400 when a tool call and its result became non-adjacent.</li><li>Merge consecutive user turns for strict providers (Gemini/Vertex), fixing an HTTP 400 (&quot;roles must alternate&quot;) after compaction or when a turn is steered in right after a tool result.</li><li>Micro-compaction now defaults off.</li></ul></li><li>Refactor the thinking effort system</li><li>Add a server-side key-value store API for persisting web UI preferences to the user&#39;s data directory.</li></ul><h2 id="_0-20-3-2026-06-30" tabindex="-1">0.20.3 (2026-06-30) <a class="header-anchor" href="#_0-20-3-2026-06-30" aria-label="Permalink to &quot;0.20.3 (2026-06-30)&quot;">​</a></h2><h3 id="bug-fixes-29" tabindex="-1">Bug Fixes <a class="header-anchor" href="#bug-fixes-29" aria-label="Permalink to &quot;Bug Fixes&quot;">​</a></h3><ul><li>Fix provider error messages rendering as blank lines in the TUI when the server returns an HTML error page.</li><li>Fix the web composer being hidden behind the mobile Safari toolbar and the page auto-zooming when the composer is focused.</li></ul><h3 id="polish-24" tabindex="-1">Polish <a class="header-anchor" href="#polish-24" aria-label="Permalink to &quot;Polish&quot;">​</a></h3><ul><li>Refresh provider model lists automatically in the background instead of only at startup, so newly available models appear without restarting.</li><li>Glob now uses ripgrep, so it respects .gitignore by default, supports brace patterns, returns only files, and keeps partial results with a warning when some directories are unreadable.</li></ul><h3 id="refactors-9" tabindex="-1">Refactors <a class="header-anchor" href="#refactors-9" aria-label="Permalink to &quot;Refactors&quot;">​</a></h3><ul><li>Align malformed tool call argument handling with schema validation fallback.</li></ul><h2 id="_0-20-2-2026-06-29" tabindex="-1">0.20.2 (2026-06-29) <a class="header-anchor" href="#_0-20-2-2026-06-29" aria-label="Permalink to &quot;0.20.2 (2026-06-29)&quot;">​</a></h2><h3 id="features-17" tabindex="-1">Features <a class="header-anchor" href="#features-17" aria-label="Permalink to &quot;Features&quot;">​</a></h3><ul><li>Support the Anthropic-compatible protocol for Kimi Code, including video input.</li><li>Add a completion sound and question notifications to the web UI, with separate Settings toggles for completion notifications, question notifications, and sound. Question notifications default off so question text only reaches your desktop after you opt in.</li><li>Add <code>KIMI_CODE_CUSTOM_HEADERS</code> for custom outbound LLM request headers, and send the <code>User-Agent</code> header to non-Kimi providers. Set <code>KIMI_CODE_CUSTOM_HEADERS</code> to newline-separated <code>Name: Value</code> lines.</li><li>Add an optional <code>exclude_empty</code> parameter to the session list API to omit sessions that have no messages.</li></ul><h3 id="bug-fixes-30" tabindex="-1">Bug Fixes <a class="header-anchor" href="#bug-fixes-30" aria-label="Permalink to &quot;Bug Fixes&quot;">​</a></h3><ul><li>Recover from provider 413 context overflows by compacting before retrying.</li><li>Cap compaction output at 128k tokens by default to avoid provider <code>max_tokens</code> errors.</li><li>Fix compaction ignoring the configured max output size.</li><li>Fix unnecessary full-screen redraws when typing in the input box or toggling the slash panel.</li><li>Keep unsent composer attachments scoped to their session in the web UI, so switching sessions no longer leaks them into another session&#39;s next message.</li><li>Fix the web composer occasionally keeping typed text after sending the first message of a new session.</li><li>Fix debug timing output lingering after undoing a turn.</li><li>Fix working tips getting squeezed against the agent swarm progress bar.</li></ul><h3 id="polish-25" tabindex="-1">Polish <a class="header-anchor" href="#polish-25" aria-label="Permalink to &quot;Polish&quot;">​</a></h3><ul><li>Rework the web ask-user-question card into a step-by-step wizard so multi-question navigation and the final Submit action are easier to see.</li><li>In the bundled web UI, a new session is now created only when the first message is sent, so <code>+ New</code> without a workspace opens the composer instead of making an empty session.</li><li>Restore each session&#39;s scroll position when switching back to it in the web UI.</li><li>Keep the open side panel when switching between sessions in the web UI.</li><li>Scope the web composer&#39;s up/down input history to the current session instead of sharing it across all sessions.</li><li>In the bundled web UI, <code>/new</code> and <code>/clear</code> are now aliases that open the session onboarding composer and focus the input. iOS auto-zoom is prevented by keeping text inputs at 16px instead of disabling viewport scaling.</li><li>Hide unused &quot;New Session&quot; entries from the web session list by default.</li><li>Remove the <code>/sessions</code> slash command from the web UI; the sidebar already covers session browsing.</li><li>Show the first five sessions per workspace in the web sidebar instead of ten.</li><li>Replace the web composer attach button&#39;s plus icon with an image icon.</li></ul><h3 id="refactors-10" tabindex="-1">Refactors <a class="header-anchor" href="#refactors-10" aria-label="Permalink to &quot;Refactors&quot;">​</a></h3><ul><li>Route Kimi Code models on the Anthropic-compatible protocol through the beta Messages API.</li><li>Upgrade web markdown renderer dependencies (katex, markstream-vue, shiki) for bug fixes and performance improvements.</li><li>Add provider type and protocol attributes to turn and API error telemetry.</li></ul><h2 id="_0-20-1-2026-06-26" tabindex="-1">0.20.1 (2026-06-26) <a class="header-anchor" href="#_0-20-1-2026-06-26" aria-label="Permalink to &quot;0.20.1 (2026-06-26)&quot;">​</a></h2><h3 id="features-18" tabindex="-1">Features <a class="header-anchor" href="#features-18" aria-label="Permalink to &quot;Features&quot;">​</a></h3><ul><li>Plugins now support declaring lifecycle hooks in <code>kimi.plugin.json</code> to run scripts at specific stages. See <a href="./../customization/plugins.html#hooks-in-plugins">Hooks in Plugins</a>.</li><li><code>/feedback</code> now supports attaching diagnostic logs and codebase context.</li><li>Add the <code>kimi update</code> command, equivalent to <code>kimi upgrade</code>, for upgrading to the latest version.</li><li><code>kimi web</code> adds the <code>--allowed-host &lt;host&gt;</code> option to add a specified Host to the DNS-rebinding allowlist; 403 errors now explain how to allow it via <code>--allowed-host</code> or <code>KIMI_CODE_ALLOWED_HOSTS</code>, e.g. <code>kimi web --allowed-host example.com</code>.</li></ul><h3 id="bug-fixes-31" tabindex="-1">Bug Fixes <a class="header-anchor" href="#bug-fixes-31" aria-label="Permalink to &quot;Bug Fixes&quot;">​</a></h3><ul><li>Fix kimi server failing to start on Windows after the first run.</li><li>Fix the Web UI opened by the <code>/web</code> command not signing in automatically; the terminal now prints the access token.</li><li>Cap chat-completions providers&#39; <code>max_tokens</code> to the remaining context window, avoiding context overflow and invalid parameter errors.</li></ul><h3 id="polish-26" tabindex="-1">Polish <a class="header-anchor" href="#polish-26" aria-label="Permalink to &quot;Polish&quot;">​</a></h3><ul><li>Optimize the default system prompt and built-in tool descriptions to stop the agent from blocking background tasks, unify tool guidance across profiles, and surface previously missing tool-result details (fetched-page mode, Grep match totals).</li><li>Cache rendered message lines to keep the terminal responsive in long conversations.</li><li>Retain only recent turns in the transcript and collapse older steps within each turn to keep long sessions responsive.</li><li>Make the web chat input grow with its content and add an expandable editor for longer messages.</li><li>Show the done / in progress / pending breakdown of hidden todos in the collapsed todo panel.</li></ul><h2 id="_0-20-0-2026-06-26" tabindex="-1">0.20.0 (2026-06-26) <a class="header-anchor" href="#_0-20-0-2026-06-26" aria-label="Permalink to &quot;0.20.0 (2026-06-26)&quot;">​</a></h2><h3 id="features-19" tabindex="-1">Features <a class="header-anchor" href="#features-19" aria-label="Permalink to &quot;Features&quot;">​</a></h3><ul><li>Add shell mode to the TUI. Type <code>!</code> in the input box to enable it. For long-running commands, press Ctrl+B to move them to the background. For example, you can run <code>!gh auth login</code> to sign in to the GitHub CLI without opening a new terminal.</li><li>Add a <code>--host</code> CLI option so <code>kimi web --host</code> can expose the server to the internet, with hardened token authentication, rate limiting, and other security measures.</li><li>Render LaTeX display math (<code>$$…$$</code>) in the web UI.</li></ul><h3 id="bug-fixes-32" tabindex="-1">Bug Fixes <a class="header-anchor" href="#bug-fixes-32" aria-label="Permalink to &quot;Bug Fixes&quot;">​</a></h3><ul><li>Fix a startup crash on Linux caused by an unhandled native clipboard error.</li><li>Fix <code>kimi web</code> and <code>/web</code> failing to start the background server daemon on Windows with <code>spawn EFTYPE</code> when the CLI is installed via npm/pnpm or run from source. The official single-binary install script was not affected.</li><li>Fix the terminal window repeatedly losing focus on Linux Wayland, which broke IME input.</li><li>Stop auto-dismissing questions in the web UI after 60 seconds so they wait for the user&#39;s answer.</li><li>Fix explore subagents silently losing git context when git commands time out or the directory is not a repository.</li><li>Fix Ctrl-C during compaction so it clears a pending editor draft first instead of cancelling immediately.</li><li>Fix MCP server working directories when sessions are hosted by the web server.</li><li>Fix duplicate session snapshot reloads in the bundled web UI during resync.</li><li>Fix truncated skill descriptions missing an ellipsis in the model&#39;s skill listing.</li></ul><h3 id="polish-27" tabindex="-1">Polish <a class="header-anchor" href="#polish-27" aria-label="Permalink to &quot;Polish&quot;">​</a></h3><ul><li>Redesign <code>/plugins</code> as a single tabbed panel: <strong>Installed</strong> (manage installed plugins — toggle, remove, MCP, details, reload), <strong>Official</strong> (Kimi-maintained marketplace plugins), <strong>Third-party</strong> (marketplace plugins from other publishers), and <strong>Custom</strong> (install straight from a GitHub URL, zip URL, or local path). Use <code>Tab</code> / <code>Shift-Tab</code> to switch tabs.</li><li>Show a line-by-line diff when the agent edits or writes a file in the web chat.</li><li>Show the plan body and approach choices in the plan review card when exiting plan mode in the web UI.</li><li>Show the full accumulated progress of a subagent in its detail panel, with concise tool-call summaries instead of raw JSON.</li><li><code>/reload</code> now refreshes the assistant&#39;s view of plugin skills, so plugin changes take effect in the current session instead of requiring a new one.</li><li>Replace silent AGENTS.md truncation with a visible warning in the TUI status bar and web UI.</li><li>Add a confirmation prompt before installing third-party plugins.</li><li>Show update badges on the <code>/plugins</code> Installed tab, where Enter now installs the available update and I opens plugin details.</li><li>Add a copy button to user messages in the web chat.</li><li>Preserve full tool output logs when previews are truncated and link background task completion notifications to saved output.</li><li>Sync session title changes across all connected clients in server mode.</li><li>Add Ctrl+U and Ctrl+D as page up and page down shortcuts in the task output viewer.</li><li>Add a hint to the per-turn step limit error pointing users to the <code>loop_control.max_steps_per_turn</code> config option.</li><li>Reduce streaming redraw cost for long assistant messages with code blocks.</li><li>Page the web session list per workspace so the first screen no longer fetches every session up front.</li><li>Keep the web session sidebar from re-rendering on every streaming token to improve rendering performance.</li><li>Create missing parent directories automatically when writing a file.</li><li>Improve the image paste hint.</li></ul><h2 id="_0-19-2-2026-06-24" tabindex="-1">0.19.2 (2026-06-24) <a class="header-anchor" href="#_0-19-2-2026-06-24" aria-label="Permalink to &quot;0.19.2 (2026-06-24)&quot;">​</a></h2><h3 id="features-20" tabindex="-1">Features <a class="header-anchor" href="#features-20" aria-label="Permalink to &quot;Features&quot;">​</a></h3><ul><li>Keep drag-and-drop workspace reordering in the web sidebar, with sort order persisted locally; sessions now also float to the top of their group as soon as a new message arrives.</li><li>Add an Alt+S shortcut in the model picker to switch the model for the current session only, without saving it as the default.</li><li>Add a Ctrl+T shortcut to expand and collapse a truncated todo list.</li><li>Add <code>-c</code> as a shorthand for <code>--continue</code>.</li></ul><h3 id="bug-fixes-33" tabindex="-1">Bug Fixes <a class="header-anchor" href="#bug-fixes-33" aria-label="Permalink to &quot;Bug Fixes&quot;">​</a></h3><ul><li>Fix yolo mode in the web app auto-approving plan reviews and sensitive file access.</li><li>Fix resume not realigning a tool call that was interrupted mid-history.</li><li>Fix the composer&#39;s ↑/↓ input-history recall doing nothing right after the first message of a new session.</li><li>Fix stale rows occasionally leaving duplicate input boxes after tall content shrinks.</li><li>Fix inline images being rendered as broken escape sequences in the transcript.</li><li>Fix code blocks nested inside list items rendering blank in the web chat after a turn finishes generating.</li><li>Fix the Tab key unexpectedly opening the file completion list.</li><li>Fix clipboard copy actions in the web UI when served over plain HTTP.</li><li>Fix the web question prompt missing the free-text Other option.</li><li>Fix web chat stop actions so stale prompt ids fall back to cancelling the active session.</li></ul><h3 id="polish-28" tabindex="-1">Polish <a class="header-anchor" href="#polish-28" aria-label="Permalink to &quot;Polish&quot;">​</a></h3><ul><li>Read large text files in bounded memory and read tail lines without scanning whole files.</li><li>Show the command in running Bash tool cards and allow expanding it with Ctrl+O before the result arrives.</li><li>Allow the web sidebar and detail panel to be resized up to the available viewport width, keeping their resize handles reachable on narrow windows.</li><li>Show subcommand suggestions after Tab-completing a slash command name.</li><li>Show a transient footer hint when an image is detected in the clipboard, displaying the platform-appropriate paste shortcut.</li><li>Persist the collapsed state of workspace groups in the web sidebar across page reloads.</li><li>Add a development-mode indicator to the web sidebar for local development.</li><li>Optimize the loading tips display.</li></ul><h3 id="refactors-11" tabindex="-1">Refactors <a class="header-anchor" href="#refactors-11" aria-label="Permalink to &quot;Refactors&quot;">​</a></h3><ul><li>Reorganize the web app&#39;s components into area subdirectories (chat/settings/dialogs/mobile) and refresh the component path comments.</li><li>Extract several composer pieces into reusable composables.</li><li>Extract pure turn-rendering helpers out of the chat pane into their own module.</li><li>Extract the beta conversation outline (table of contents) into its own component.</li><li>Extract the workspace group rendering out of the sidebar into its own component.</li></ul><h2 id="_0-19-1-2026-06-23" tabindex="-1">0.19.1 (2026-06-23) <a class="header-anchor" href="#_0-19-1-2026-06-23" aria-label="Permalink to &quot;0.19.1 (2026-06-23)&quot;">​</a></h2><h3 id="bug-fixes-34" tabindex="-1">Bug Fixes <a class="header-anchor" href="#bug-fixes-34" aria-label="Permalink to &quot;Bug Fixes&quot;">​</a></h3><ul><li>Fix ACP editors such as Zed failing to start a new thread.</li><li>Fix the web sidebar&#39;s unread dots getting out of sync across browser tabs.</li><li>Clear all per-session state when a session is archived or removed, so archived sessions no longer leave orphaned data behind.</li></ul><h3 id="refactors-12" tabindex="-1">Refactors <a class="header-anchor" href="#refactors-12" aria-label="Permalink to &quot;Refactors&quot;">​</a></h3><ul><li>Consolidate web client localStorage access and split the root state store and app shell into focused composables.</li></ul><h2 id="_0-19-0-2026-06-22" tabindex="-1">0.19.0 (2026-06-22) <a class="header-anchor" href="#_0-19-0-2026-06-22" aria-label="Permalink to &quot;0.19.0 (2026-06-22)&quot;">​</a></h2><h3 id="features-21" tabindex="-1">Features <a class="header-anchor" href="#features-21" aria-label="Permalink to &quot;Features&quot;">​</a></h3><ul><li>Added the ability to add extra workspace directories: <ul><li>Use the <code>/add-dir &lt;path&gt;</code> command to add extra working directories to the current session, or remember them for the project.</li><li>Use <code>kimi --add-dir &lt;path&gt;</code> to add them on startup.</li><li>Project-level local config is now managed in <code>.kimi-code/local.toml</code>; we recommend adding it to your <code>.gitignore</code>.</li></ul></li><li>Allow long-running foreground commands and subagents to be moved into background tasks with <code>Ctrl+B</code>, and inspect them via the <code>/tasks</code> panel.</li></ul><h3 id="bug-fixes-35" tabindex="-1">Bug Fixes <a class="header-anchor" href="#bug-fixes-35" aria-label="Permalink to &quot;Bug Fixes&quot;">​</a></h3><ul><li>Surface provider safety-policy blocks instead of silently treating them as completed turns, and prevent the context token count from dropping to zero after a filtered response.</li><li>Fix provider requests failing when restored conversation history contains empty text content blocks.</li><li>Detect the real image format from file contents when reading media, so a mismatched filename extension no longer produces a data URL the model API rejects.</li><li>Fix commands flashing an empty console window on Windows.</li><li>Stop showing unread dots on cancelled or failed sessions in the web sidebar.</li></ul><h3 id="polish-29" tabindex="-1">Polish <a class="header-anchor" href="#polish-29" aria-label="Permalink to &quot;Polish&quot;">​</a></h3><ul><li>Speed up session snapshot loading with a direct disk reader and a request timeout safeguard, keeping the previous path as a legacy fallback.</li><li>Show longer branch names in the web chat header and expose the full name on hover.</li><li>Keep the web page title fixed instead of changing with the session or workspace name.</li><li>Polish file mention UX.</li></ul><h3 id="refactors-13" tabindex="-1">Refactors <a class="header-anchor" href="#refactors-13" aria-label="Permalink to &quot;Refactors&quot;">​</a></h3><ul><li>Unify image format detection when sniffing fails.</li><li>Consolidate web client localStorage access and decouple appearance/notification state into dedicated modules.</li></ul><h2 id="_0-18-0-2026-06-18" tabindex="-1">0.18.0 (2026-06-18) <a class="header-anchor" href="#_0-18-0-2026-06-18" aria-label="Permalink to &quot;0.18.0 (2026-06-18)&quot;">​</a></h2><h3 id="features-22" tabindex="-1">Features <a class="header-anchor" href="#features-22" aria-label="Permalink to &quot;Features&quot;">​</a></h3><ul><li>Add session filtering to the web sidebar, filtering by title and the last user prompt.</li><li>Add scroll-up lazy loading for older messages in the web chat session view.</li><li>Add an environment variable to cap AgentSwarm concurrency during the initial ramp, so large swarms do not trip provider rate limits as easily.</li></ul><h3 id="bug-fixes-36" tabindex="-1">Bug Fixes <a class="header-anchor" href="#bug-fixes-36" aria-label="Permalink to &quot;Bug Fixes&quot;">​</a></h3><ul><li>Fix the web app only loading the 20 most recent sessions.</li><li>Fix web slash skill selection sending immediately and allow slash search to match skill names by substring.</li><li>Fix the highlighted web slash command not staying visible while navigating a long slash menu.</li><li>Fix incorrect display after archiving the last session.</li><li>Fix the web login slash command description to match the browser authorization flow.</li></ul><h3 id="polish-30" tabindex="-1">Polish <a class="header-anchor" href="#polish-30" aria-label="Permalink to &quot;Polish&quot;">​</a></h3><ul><li>Redesign the web OAuth login dialog so the order of steps is unambiguous.</li><li>Show the current version in web settings.</li><li>Allow long web slash command names and descriptions to wrap without overflowing the slash menu.</li><li>Add <code>/reload</code> suggestion in plugin-change hints.</li></ul><h2 id="_0-17-1-2026-06-17" tabindex="-1">0.17.1 (2026-06-17) <a class="header-anchor" href="#_0-17-1-2026-06-17" aria-label="Permalink to &quot;0.17.1 (2026-06-17)&quot;">​</a></h2><h3 id="bug-fixes-37" tabindex="-1">Bug Fixes <a class="header-anchor" href="#bug-fixes-37" aria-label="Permalink to &quot;Bug Fixes&quot;">​</a></h3><ul><li>Fix the <code>kimi web</code> command failing to start in the background.</li><li>Stop the background local server from locking the directory it was started in.</li><li>Prevent the web login dialog from closing when clicking the backdrop.</li></ul><h3 id="polish-31" tabindex="-1">Polish <a class="header-anchor" href="#polish-31" aria-label="Permalink to &quot;Polish&quot;">​</a></h3><ul><li>Group the default model dropdown in web settings by provider.</li></ul><h2 id="_0-17-0-2026-06-17" tabindex="-1">0.17.0 (2026-06-17) <a class="header-anchor" href="#_0-17-0-2026-06-17" aria-label="Permalink to &quot;0.17.0 (2026-06-17)&quot;">​</a></h2><h3 id="features-23" tabindex="-1">Features <a class="header-anchor" href="#features-23" aria-label="Permalink to &quot;Features&quot;">​</a></h3><ul><li>Add Kimi Code Web mode, which you can start with <code>kimi web</code> or <code>/web</code> in the CLI, and continue sessions in a browser chat interface.</li></ul><h3 id="bug-fixes-38" tabindex="-1">Bug Fixes <a class="header-anchor" href="#bug-fixes-38" aria-label="Permalink to &quot;Bug Fixes&quot;">​</a></h3><ul><li>Show the underlying connection error when OAuth token refresh fails after internal retries, instead of prompting for login. Token refresh failures are no longer re-retried at the agent loop level.</li><li>Restore the turn counter from persisted loop events on resume so post-resume turns no longer reuse turn ids that already appear in history.</li></ul><h3 id="polish-32" tabindex="-1">Polish <a class="header-anchor" href="#polish-32" aria-label="Permalink to &quot;Polish&quot;">​</a></h3><ul><li>Skip debug TPS when the output stream is too short to measure reliably.</li></ul><h2 id="_0-16-0-2026-06-16" tabindex="-1">0.16.0 (2026-06-16) <a class="header-anchor" href="#_0-16-0-2026-06-16" aria-label="Permalink to &quot;0.16.0 (2026-06-16)&quot;">​</a></h2><h3 id="features-24" tabindex="-1">Features <a class="header-anchor" href="#features-24" aria-label="Permalink to &quot;Features&quot;">​</a></h3><ul><li>Add a built-in <code>kimi vis</code> command that launches the session visualizer in your browser, pointed at your local sessions. Supports <code>--port</code>/<code>--host</code>, <code>--no-open</code>, and <code>kimi vis &lt;sessionId&gt;</code> deep-links.</li></ul><h3 id="bug-fixes-39" tabindex="-1">Bug Fixes <a class="header-anchor" href="#bug-fixes-39" aria-label="Permalink to &quot;Bug Fixes&quot;">​</a></h3><ul><li>Stop Anthropic-compatible providers from reading ambient Anthropic shell credentials and custom headers.</li><li>Fix repeated compaction handling when context remains over the blocking threshold.</li><li>Prevent session shutdown from resuming the agent when stopping background tasks.</li><li>Project session replay ranges over rendered replay records instead of raw persisted records.</li><li>Close wrapped output streams when buffered readers are destroyed.</li></ul><h3 id="polish-33" tabindex="-1">Polish <a class="header-anchor" href="#polish-33" aria-label="Permalink to &quot;Polish&quot;">​</a></h3><ul><li>Reduce the maximum height of the <code>/btw</code> side panel from half to one-third of the terminal.</li><li>Polish queue pane styling.</li><li>Add configurable banner display frequencies with local display state.</li></ul><h3 id="refactors-14" tabindex="-1">Refactors <a class="header-anchor" href="#refactors-14" aria-label="Permalink to &quot;Refactors&quot;">​</a></h3><ul><li>Remove redundant LLM request logging context plumbing.</li></ul><h2 id="_0-15-0-2026-06-15" tabindex="-1">0.15.0 (2026-06-15) <a class="header-anchor" href="#_0-15-0-2026-06-15" aria-label="Permalink to &quot;0.15.0 (2026-06-15)&quot;">​</a></h2><h3 id="features-25" tabindex="-1">Features <a class="header-anchor" href="#features-25" aria-label="Permalink to &quot;Features&quot;">​</a></h3><ul><li>Add an all-sessions picker view with name search, paginated browsing, and clipboard-ready resume commands for sessions in other working directories.</li><li>Add support for legacy SSE MCP servers alongside stdio and streamable HTTP transports.</li></ul><h3 id="bug-fixes-40" tabindex="-1">Bug Fixes <a class="header-anchor" href="#bug-fixes-40" aria-label="Permalink to &quot;Bug Fixes&quot;">​</a></h3><ul><li>Recover resumed sessions when an interrupted tool call result was not recorded.</li><li>Stop writing resume version markers into persisted agent metadata.</li><li>Do not carry obsolete legacy loop, background, plan, yolo, or unknown experimental flags into migrated config files.</li><li>Repair mismatched JSON Schema types emitted by Xcode 26.5 MCP server for Moonshot compatibility.</li></ul><h3 id="polish-34" tabindex="-1">Polish <a class="header-anchor" href="#polish-34" aria-label="Permalink to &quot;Polish&quot;">​</a></h3><ul><li>Keep TUI components within narrow terminal widths by wrapping, compacting, or truncating lines that could exceed the render width.</li><li>Prompt the CLI to show one brief same-language status sentence before non-trivial tool calls.</li><li>Extend the same-language rule to the model&#39;s reasoning, so thinking follows the user&#39;s language while keeping code and technical terms in their original form.</li><li>Read media files using header-detected types before falling back to media extensions.</li><li>Prioritize clearing draft editor text before Ctrl-C cancels an active stream.</li><li>Collapse hidden directories in the workspace prompt and explain how to inspect them.</li><li>Include the skill&#39;s directory on the loaded-skill context block so the agent can locate a skill&#39;s bundled resources (scripts, templates) after it is invoked.</li><li>Show the all-sessions toggle hint when the current working directory has no sessions.</li><li>Clarify that compaction summaries must be emitted in the final answer.</li><li>Clarify AGENTS.md prompt guidance and mark truncated instruction files.</li></ul><h3 id="refactors-15" tabindex="-1">Refactors <a class="header-anchor" href="#refactors-15" aria-label="Permalink to &quot;Refactors&quot;">​</a></h3><ul><li>Resolve model capabilities through a static lookup instead of instantiating a temporary provider.</li><li>Decouple agent skill access from session-specific registry implementations.</li><li>Optimize the npm packaging system.</li></ul><h2 id="_0-14-3-2026-06-14" tabindex="-1">0.14.3 (2026-06-14) <a class="header-anchor" href="#_0-14-3-2026-06-14" aria-label="Permalink to &quot;0.14.3 (2026-06-14)&quot;">​</a></h2><h3 id="polish-35" tabindex="-1">Polish <a class="header-anchor" href="#polish-35" aria-label="Permalink to &quot;Polish&quot;">​</a></h3><ul><li>Refresh provider model metadata before opening the model picker.</li></ul><h2 id="_0-14-2-2026-06-12" tabindex="-1">0.14.2 (2026-06-12) <a class="header-anchor" href="#_0-14-2-2026-06-12" aria-label="Permalink to &quot;0.14.2 (2026-06-12)&quot;">​</a></h2><h3 id="bug-fixes-41" tabindex="-1">Bug Fixes <a class="header-anchor" href="#bug-fixes-41" aria-label="Permalink to &quot;Bug Fixes&quot;">​</a></h3><ul><li>Fix endless desktop notifications in iTerm2 by only sending terminal progress sequences to terminals that support them.</li><li>Show completed and cancelled compaction records correctly when resuming a session.</li><li>Drop invalid config.toml sections with a warning instead of failing to start.</li></ul><h3 id="polish-36" tabindex="-1">Polish <a class="header-anchor" href="#polish-36" aria-label="Permalink to &quot;Polish&quot;">​</a></h3><ul><li>Stream foreground Bash stdout and stderr while commands are still running.</li><li>Allow <code>--auto</code>, <code>--yolo</code>, and <code>--plan</code> to be combined with <code>--session</code> or <code>--continue</code> by applying the requested mode to the resumed session.</li><li>Qualify sub-skill names with their parent prefix and expose sub-skills as dotted slash commands in the TUI.</li><li>Sync custom registry provider additions, removals, and rotated registry keys during startup refresh.</li></ul><h2 id="_0-14-1-2026-06-12" tabindex="-1">0.14.1 (2026-06-12) <a class="header-anchor" href="#_0-14-1-2026-06-12" aria-label="Permalink to &quot;0.14.1 (2026-06-12)&quot;">​</a></h2><h3 id="bug-fixes-42" tabindex="-1">Bug Fixes <a class="header-anchor" href="#bug-fixes-42" aria-label="Permalink to &quot;Bug Fixes&quot;">​</a></h3><ul><li>Cancel active turns during session shutdown so foreground shell commands do not outlive prompt-mode exits.</li><li>Stop background tasks by default when sessions close.</li><li>Prevent overlapping interactive agent requests from using the wrong active agent.</li><li>Fix premature stream close errors when shell processes time out or are killed.</li><li>Degrade unsupported audio/video to placeholder text and reattach tool result media instead of silently dropping them.</li><li>Send OpenAI Responses system prompts as request instructions.</li><li>Propagate configured execution environment overrides across spawned processes.</li><li>Fix ACP file reads and edits for Windows workspaces opened through IDE clients.</li><li>Require AgentSwarm tool calls to run alone in a model response.</li></ul><h3 id="polish-37" tabindex="-1">Polish <a class="header-anchor" href="#polish-37" aria-label="Permalink to &quot;Polish&quot;">​</a></h3><ul><li>Add runtime support for dynamic MCP server updates, reference skills, replay timestamps, and Node file uploads.</li><li>Add a YOLO choice when starting swarm tasks from Manual mode.</li><li>Polish builtin skills.</li><li>Find slash commands by their aliases in autocomplete — typing <code>/clear</code> now suggests <code>new (clear)</code>.</li><li>Wrap long command and skill descriptions in the autocomplete menu onto a second line instead of cutting them off.</li><li>Display a tips banner below the welcome panel on startup.</li></ul><h2 id="_0-14-0-2026-06-10" tabindex="-1">0.14.0 (2026-06-10) <a class="header-anchor" href="#_0-14-0-2026-06-10" aria-label="Permalink to &quot;0.14.0 (2026-06-10)&quot;">​</a></h2><h3 id="features-26" tabindex="-1">Features <a class="header-anchor" href="#features-26" aria-label="Permalink to &quot;Features&quot;">​</a></h3><ul><li>Add an <code>Interrupt</code> hook event that fires when the user interrupts a turn (e.g. pressing Esc), letting hooks observe the turn stopping instead of getting stuck on a working state.</li></ul><h3 id="bug-fixes-43" tabindex="-1">Bug Fixes <a class="header-anchor" href="#bug-fixes-43" aria-label="Permalink to &quot;Bug Fixes&quot;">​</a></h3><ul><li>Preserve image outputs from tools when using OpenAI-compatible chat completions.</li></ul><h2 id="_0-13-1-2026-06-10" tabindex="-1">0.13.1 (2026-06-10) <a class="header-anchor" href="#_0-13-1-2026-06-10" aria-label="Permalink to &quot;0.13.1 (2026-06-10)&quot;">​</a></h2><h3 id="bug-fixes-44" tabindex="-1">Bug Fixes <a class="header-anchor" href="#bug-fixes-44" aria-label="Permalink to &quot;Bug Fixes&quot;">​</a></h3><ul><li>Prevent forking sessions during active turns and consolidate wire protocol definitions into a shared internal package.</li><li>Fix Kimi Datasource to use the matching OAuth credentials and service endpoint for the active Kimi Code environment.</li><li>Fix goal marker text overflowing terminal width.</li></ul><h3 id="polish-38" tabindex="-1">Polish <a class="header-anchor" href="#polish-38" aria-label="Permalink to &quot;Polish&quot;">​</a></h3><ul><li>Add Claude Fable 5 support to the Anthropic provider.</li><li>Add an interactive undo selector and clearer undo-limit messages.</li><li>YOLO mode no longer asks before writing or editing files outside the working directory.</li><li>Clarify active skill prompts so loaded skills are no longer represented as system reminders.</li><li>Tighten file tool guidance to route incremental edits through Edit.</li></ul><h2 id="_0-13-0-2026-06-10" tabindex="-1">0.13.0 (2026-06-10) <a class="header-anchor" href="#_0-13-0-2026-06-10" aria-label="Permalink to &quot;0.13.0 (2026-06-10)&quot;">​</a></h2><h3 id="features-27" tabindex="-1">Features <a class="header-anchor" href="#features-27" aria-label="Permalink to &quot;Features&quot;">​</a></h3><ul><li>Add custom color themes. Define your own palette as a JSON file in <code>~/.kimi-code/themes/</code>, or generate one with the built-in <code>/custom-theme</code> skill command.</li><li>Add <code>/import-from-cc-codex</code> to import selected Claude Code and Codex instructions, Skills, and MCP settings.</li><li>Show available plugin updates in the marketplace.</li></ul><h3 id="bug-fixes-45" tabindex="-1">Bug Fixes <a class="header-anchor" href="#bug-fixes-45" aria-label="Permalink to &quot;Bug Fixes&quot;">​</a></h3><ul><li>Fix Windows builds and development launches that could fail when package binaries resolve to command shims.</li><li>Fix device login to keep the URL and code visible when the browser cannot be opened.</li></ul><h3 id="polish-39" tabindex="-1">Polish <a class="header-anchor" href="#polish-39" aria-label="Permalink to &quot;Polish&quot;">​</a></h3><ul><li>Clarify grouped subagent progress with active status breakdowns and elapsed time.</li><li>Truncate queued message display to a single line with ellipsis when it exceeds terminal width.</li></ul><h2 id="_0-12-1-2026-06-09" tabindex="-1">0.12.1 (2026-06-09) <a class="header-anchor" href="#_0-12-1-2026-06-09" aria-label="Permalink to &quot;0.12.1 (2026-06-09)&quot;">​</a></h2><h3 id="bug-fixes-46" tabindex="-1">Bug Fixes <a class="header-anchor" href="#bug-fixes-46" aria-label="Permalink to &quot;Bug Fixes&quot;">​</a></h3><ul><li>Allow obsolete experimental config entries to remain without blocking startup.</li><li>Pass through xhigh reasoning effort for OpenAI-compatible chat completions requests.</li></ul><h2 id="_0-12-0-2026-06-09" tabindex="-1">0.12.0 (2026-06-09) <a class="header-anchor" href="#_0-12-0-2026-06-09" aria-label="Permalink to &quot;0.12.0 (2026-06-09)&quot;">​</a></h2><h3 id="features-28" tabindex="-1">Features <a class="header-anchor" href="#features-28" aria-label="Permalink to &quot;Features&quot;">​</a></h3><ul><li>Add the <code>/swarm</code> command for running agent swarms with live progress and rate-limit-aware retries.</li><li>Make goals, background questions, and sub-skill discovery available without experimental opt-ins.</li><li>Honor the standard <code>HTTP_PROXY</code> / <code>HTTPS_PROXY</code> / <code>ALL_PROXY</code> / <code>NO_PROXY</code> environment variables, including SOCKS proxies, for all outbound traffic.</li><li>Support Homebrew installations.</li><li>Enable micro compaction by default. Disable via <code>/experiments</code>.</li></ul><h3 id="bug-fixes-47" tabindex="-1">Bug Fixes <a class="header-anchor" href="#bug-fixes-47" aria-label="Permalink to &quot;Bug Fixes&quot;">​</a></h3><ul><li>Fix ACP slash skill routing, bootstrap context reads, file and permission edge cases, subagent event handling, and stale-file edit messaging.</li><li>Fix goal resume behavior by restoring goal state from agent records.</li><li>Fix thinking text and tool output display for subagents.</li><li>Fix session workdir mismatch on Windows caused by inconsistent path separators.</li><li>Fix the <code>/mcp</code> status panel border being broken by multi-line MCP server errors, which are now folded onto a single row.</li><li>Detect Git Bash installed through Scoop and other Git shims on Windows.</li><li>Show the underlying error when migration fails.</li><li>Allow the startup session picker to exit with repeated Ctrl-C or Ctrl-D.</li></ul><h3 id="polish-40" tabindex="-1">Polish <a class="header-anchor" href="#polish-40" aria-label="Permalink to &quot;Polish&quot;">​</a></h3><ul><li>Remove the per-turn auto-compaction limit so long conversations can keep compacting instead of failing early.</li><li>Improve goal mode outcome handling with follow-up messages, safer error pauses, and clearer TUI transcript display.</li><li>Show full plan cards directly and remove the Plan card keyboard shortcut.</li><li>Wrap long single-line shell commands in approval prompts so the full command remains visible.</li><li>Rework file reference completion in the TUI.</li><li>Load Kimi-specific user Skills and global agent instructions from <code>KIMI_CODE_HOME</code> when it is set.</li></ul><h2 id="_0-11-0-2026-06-05" tabindex="-1">0.11.0 (2026-06-05) <a class="header-anchor" href="#_0-11-0-2026-06-05" aria-label="Permalink to &quot;0.11.0 (2026-06-05)&quot;">​</a></h2><h3 id="features-29" tabindex="-1">Features <a class="header-anchor" href="#features-29" aria-label="Permalink to &quot;Features&quot;">​</a></h3><ul><li><p>Add experimental sub-skill discovery gated by the <code>KIMI_CODE_EXPERIMENTAL_SUB_SKILL</code> environment variable. Ships the <code>sub-skill</code> builtin bundle (<code>sub-skill.review</code>, <code>sub-skill.consolidate</code>) for inventorying and consolidating skills into hierarchical groups.</p></li><li><p>Add the following environment variables:</p><ul><li><code>KIMI_MODEL_TEMPERATURE</code>, <code>KIMI_MODEL_TOP_P</code> — sampling parameters applied globally to any <code>kimi</code> provider (not tied to <code>KIMI_MODEL_NAME</code>).</li><li><code>KIMI_MODEL_THINKING_KEEP</code> — Moonshot preserved-thinking passthrough (<code>thinking.keep</code>), injected only while Thinking is on.</li><li><code>KIMI_CODE_NO_AUTO_UPDATE</code> (legacy alias <code>KIMI_CLI_NO_AUTO_UPDATE</code>) — fully disables the update preflight (no check, background install, or prompt).</li></ul></li><li><p>Show built-in skills as direct slash commands and group them ahead of external skill commands.</p></li></ul><h3 id="bug-fixes-48" tabindex="-1">Bug Fixes <a class="header-anchor" href="#bug-fixes-48" aria-label="Permalink to &quot;Bug Fixes&quot;">​</a></h3><ul><li>Fix slash command autocomplete so goal text can be submitted when the cursor is before existing text.</li><li>Fix queued goals so failed promotion attempts do not lose or duplicate queued work.</li><li>Fix upcoming-goal queue handling while editing or pasting queued goals.</li><li>Ask before starting goals in YOLO mode so users can switch to Auto for unattended work.</li><li>Show concise provider filtering errors when responses are blocked before visible output.</li><li>Show &quot;unknown command&quot; instead of &quot;too many arguments&quot; when an invalid subcommand is entered.</li><li>Clamp OpenAI Chat Completions <code>xhigh</code> and <code>max</code> thinking effort to <code>high</code> unless the model supports <code>xhigh</code> on <code>v1/chat/completions</code>.</li><li>Preserve thinking effort when compacting long conversations.</li><li>Refresh provider model metadata when capabilities change without model ID changes.</li></ul><h3 id="polish-41" tabindex="-1">Polish <a class="header-anchor" href="#polish-41" aria-label="Permalink to &quot;Polish&quot;">​</a></h3><ul><li>Show the upcoming-goal confirmation with the same accent treatment as goal lifecycle messages.</li><li>Start upcoming goals immediately when there is no active goal to wait for. Support multiline edits when managing upcoming goals.</li><li>Use a fixed 30-minute timeout for subagents and show concise resume instructions when they time out.</li><li>Highlight goal queue subcommands while typing slash commands.</li></ul><h2 id="_0-10-1-2026-06-05" tabindex="-1">0.10.1 (2026-06-05) <a class="header-anchor" href="#_0-10-1-2026-06-05" aria-label="Permalink to &quot;0.10.1 (2026-06-05)&quot;">​</a></h2><h3 id="bug-fixes-49" tabindex="-1">Bug Fixes <a class="header-anchor" href="#bug-fixes-49" aria-label="Permalink to &quot;Bug Fixes&quot;">​</a></h3><ul><li>Fix a crash when starting a goal in the TUI.</li></ul><h2 id="_0-10-0-2026-06-04" tabindex="-1">0.10.0 (2026-06-04) <a class="header-anchor" href="#_0-10-0-2026-06-04" aria-label="Permalink to &quot;0.10.0 (2026-06-04)&quot;">​</a></h2><h3 id="features-30" tabindex="-1">Features <a class="header-anchor" href="#features-30" aria-label="Permalink to &quot;Features&quot;">​</a></h3><ul><li>Users now can prepare several goals for the agent to work on sequentially. The agent will pick up the next goal from the queue once the current goal is completed. Use <code>/goal next &lt;objective&gt;</code> to queue a goal and <code>/goal next manage</code> to review and change the queue interactively.</li><li>Add the built-in <code>update-config</code> skill — you can now have Kimi edit its own config files.</li><li>Add persistent experimental feature toggles and a TUI panel that applies confirmed changes by reloading the current session.</li><li>Add <code>/reload</code> to reload the current session and apply updated config files, plus <code>/reload-tui</code> to reload only TUI preferences.</li><li>Add a doctor command for validating Kimi Code configuration files.</li></ul><h3 id="bug-fixes-50" tabindex="-1">Bug Fixes <a class="header-anchor" href="#bug-fixes-50" aria-label="Permalink to &quot;Bug Fixes&quot;">​</a></h3><ul><li>Normalize malformed Responses stream rate limit errors as provider rate limit failures.</li><li>Keep managed OAuth credentials scoped to their configured authentication and API endpoints.</li><li>Stop carrying active and queued goals into forked sessions.</li><li>Fail early when Git Bash is missing on Windows before starting CLI sessions.</li><li>Refresh the update target before showing foreground update prompts so the displayed version matches the install.</li><li>Point session error diagnostics to the <code>/export-debug-zip</code> command.</li><li>Set terminal tab titles without renaming the running process.</li></ul><h3 id="polish-42" tabindex="-1">Polish <a class="header-anchor" href="#polish-42" aria-label="Permalink to &quot;Polish&quot;">​</a></h3><ul><li>Start automatic background updates as soon as startup&#39;s fresh update check finds a newer version.</li><li>Set the CLI process title to kimi-code during startup.</li><li>Lowercase the stale file content message in edit tool errors.</li></ul><h3 id="refactors-16" tabindex="-1">Refactors <a class="header-anchor" href="#refactors-16" aria-label="Permalink to &quot;Refactors&quot;">​</a></h3><ul><li>Ensure Nix-packaged CLI builds can find ripgrep and fd.</li></ul><h3 id="other" tabindex="-1">Other <a class="header-anchor" href="#other" aria-label="Permalink to &quot;Other&quot;">​</a></h3><ul><li>Document the Git Bash prerequisite for Windows installs.</li></ul><h2 id="_0-9-0-2026-06-03" tabindex="-1">0.9.0 (2026-06-03) <a class="header-anchor" href="#_0-9-0-2026-06-03" aria-label="Permalink to &quot;0.9.0 (2026-06-03)&quot;">​</a></h2><h3 id="features-31" tabindex="-1">Features <a class="header-anchor" href="#features-31" aria-label="Permalink to &quot;Features&quot;">​</a></h3><ul><li>Add the <code>kimi acp</code> subcommand: kimi-code now speaks <a href="https://agentclientprotocol.com/" target="_blank" rel="noreferrer">Agent Client Protocol 0.23</a> over stdio so IDEs (Zed, JetBrains AI Chat, custom clients) can drive sessions directly — coverage matrix, Zed configuration and breaking pre-release notes are in <a href="https://moonshotai.github.io/kimi-code/en/reference/kimi-acp.html" target="_blank" rel="noreferrer">kimi acp Subcommand Page</a>.</li><li>Add <code>/btw</code> for side-channel conversations without steering the active main turn, and allow <code>/btw</code> to open the side-channel panel before entering a question.</li></ul><h3 id="bug-fixes-51" tabindex="-1">Bug Fixes <a class="header-anchor" href="#bug-fixes-51" aria-label="Permalink to &quot;Bug Fixes&quot;">​</a></h3><ul><li>Fix external editor (Ctrl+G) on Windows by removing <code>/bin/sh</code> dependency and using platform-aware shell quoting for temp file paths.</li><li>Use the OpenAI completion token field required by newer Chat Completions models.</li><li>Use configured model output limits for completion token caps.</li><li>Fix goal budget tool schemas for OpenAI-compatible providers.</li><li>Resume saved subagents lazily when they are accessed.</li></ul><h3 id="polish-43" tabindex="-1">Polish <a class="header-anchor" href="#polish-43" aria-label="Permalink to &quot;Polish&quot;">​</a></h3><ul><li>Unify the interaction and visuals across TUI dialogs and selectors.</li><li>Log enabled experimental flags at startup.</li></ul><h3 id="refactors-17" tabindex="-1">Refactors <a class="header-anchor" href="#refactors-17" aria-label="Permalink to &quot;Refactors&quot;">​</a></h3><ul><li>Allow SDK runtime creation to use a separate RPC client while preserving local CLI startup.</li></ul><h2 id="_0-8-0-2026-06-02" tabindex="-1">0.8.0 (2026-06-02) <a class="header-anchor" href="#_0-8-0-2026-06-02" aria-label="Permalink to &quot;0.8.0 (2026-06-02)&quot;">​</a></h2><h3 id="features-32" tabindex="-1">Features <a class="header-anchor" href="#features-32" aria-label="Permalink to &quot;Features&quot;">​</a></h3><ul><li><p>Add experimental goal mode for longer tasks that need more than one turn. Turn it on with <code>KIMI_CODE_EXPERIMENTAL_GOAL_COMMAND=1</code> before you start Kimi.</p><p>Use <code>/goal &lt;objective&gt;</code> in the TUI when you want Kimi to keep working on one task across turns. For example:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>/goal Fix the failing checkout test</span></span></code></pre></div><p>Kimi shows the goal in the TUI and keeps progress visible while it works. Use <code>/goal status</code>, <code>/goal pause</code>, <code>/goal resume</code>, <code>/goal cancel</code>, and <code>/goal replace &lt;objective&gt;</code> to manage the goal. This feature is still experimental. Try it and tell us what would make it more useful.</p></li><li><p>Add <code>kimi provider</code> CLI subcommand with <code>add</code>, <code>remove</code>, <code>list</code>, and <code>catalog list</code> / <code>catalog add</code> actions, so providers from a custom registry (api.json) or the public models.dev catalog can be imported and managed without launching the TUI.</p></li><li><p>Add background structured questions so agents can continue while waiting for user answers.</p></li><li><p>Add background automatic upgrades, which can be disabled in tui.toml.</p></li><li><p>Add <code>/undo</code> slash command to withdraw the last prompt from conversation history, and keep replay records in sync when a prompt is undone.</p></li><li><p>Add a <code>kimi upgrade</code> command for manually checking and upgrade Kimi Code CLI.</p></li><li><p>Add approval lifecycle hook events for observing pending and completed permission prompts.</p></li><li><p>Allow subagents to use custom tools registered on their parent agent.</p></li><li><p>Allow glob searches to target explicit absolute paths outside the workspace.</p></li></ul><h3 id="bug-fixes-52" tabindex="-1">Bug Fixes <a class="header-anchor" href="#bug-fixes-52" aria-label="Permalink to &quot;Bug Fixes&quot;">​</a></h3><ul><li>Fix cross-provider replay failures from incompatible tool call IDs and unsigned Claude thinking history.</li><li>Fix custom registry provider handling during re-import. Prevent loss of multi-provider entries and remove stale providers along with their model aliases and default model references.</li><li>Fix tool output preview rendering: trim trailing empty lines, append ellipsis to multi-line Bash command headers, and truncate long single-line output by visual wrapped lines instead of raw newline count.</li><li>Fix slash-activated skills not being recognized by the model due to missing system reminder wrapper.</li><li>Fix a crash in the <code>/sessions</code> picker on very narrow terminals by clamping every rendered line to the terminal width.</li><li>Normalize glob patterns before brace expansion to prevent incorrect path matching.</li><li>Prevent modified keyboard release sequences from appearing after exiting the CLI.</li><li>Fix Git Bash path detection on Windows by also searching <code>usr\\bin\\bash.exe</code> locations, which is where bash lives in many Git for Windows installations where <code>bin\\bash.exe</code> does not exist.</li></ul><h3 id="polish-44" tabindex="-1">Polish <a class="header-anchor" href="#polish-44" aria-label="Permalink to &quot;Polish&quot;">​</a></h3><ul><li>Show MCP server summary in the welcome panel and add configuration hints in the /mcp command output.</li><li>Point users to <code>/provider</code> instead of the removed <code>/connect</code> command in the welcome screen and the no-models-configured hint.</li><li>Append the current todo list as markdown to compaction summaries before writing them to history.</li><li>Show the full model name in the footer status bar instead of truncating the provider prefix.</li><li>Remind the model to refresh TodoList during long-running tasks and strengthen TodoList progress-tracking guidance.</li><li>Replace chalk named color with theme-aware hex in session-directory warning.</li></ul><h3 id="refactors-18" tabindex="-1">Refactors <a class="header-anchor" href="#refactors-18" aria-label="Permalink to &quot;Refactors&quot;">​</a></h3><ul><li>Consolidate background task management under the agent background runtime.</li></ul><h2 id="_0-7-0-2026-06-02" tabindex="-1">0.7.0 (2026-06-02) <a class="header-anchor" href="#_0-7-0-2026-06-02" aria-label="Permalink to &quot;0.7.0 (2026-06-02)&quot;">​</a></h2><h3 id="features-33" tabindex="-1">Features <a class="header-anchor" href="#features-33" aria-label="Permalink to &quot;Features&quot;">​</a></h3><ul><li>Add <code>/provider</code> command for managing AI providers, support custom registry imports, and introduce a tabbed model selector. It replaces the deprecated <code>/connect</code> command — use <code>/provider</code> instead.</li><li>Render scheduled reminders distinctly in the TUI, expose cron fired events to SDK clients, and report cron fire times with local timezone offsets.</li><li>Add <code>KIMI_MODEL_ADAPTIVE_THINKING</code> (and a matching <code>adaptive_thinking</code> model-alias field) to force adaptive thinking (<code>thinking: { type: &#39;adaptive&#39; }</code>) on or off, overriding the Anthropic model-name version inference. This lets custom-named compatible endpoints that back an adaptive-capable model opt in even when the model name does not encode a parseable Claude version.</li></ul><h3 id="bug-fixes-53" tabindex="-1">Bug Fixes <a class="header-anchor" href="#bug-fixes-53" aria-label="Permalink to &quot;Bug Fixes&quot;">​</a></h3><ul><li>Report truncated compaction summaries clearly and apply valid completion token budgets across supported providers.</li><li>Fix glob pattern backslash escaping and include match count in truncation messages.</li></ul><h3 id="polish-45" tabindex="-1">Polish <a class="header-anchor" href="#polish-45" aria-label="Permalink to &quot;Polish&quot;">​</a></h3><ul><li>Clarify Kimi Platform API key login labels and prompt details.</li><li>Polish a small TUI visual interaction.</li></ul><h2 id="_0-6-0-2026-05-29" tabindex="-1">0.6.0 (2026-05-29) <a class="header-anchor" href="#_0-6-0-2026-05-29" aria-label="Permalink to &quot;0.6.0 (2026-05-29)&quot;">​</a></h2><h3 id="features-34" tabindex="-1">Features <a class="header-anchor" href="#features-34" aria-label="Permalink to &quot;Features&quot;">​</a></h3><ul><li>Add a <code>KIMI_MODEL_*</code> environment-variable channel that lets you run Kimi Code against a specific model (provider type, base URL, API key, context size, capabilities, and thinking settings) without editing <code>config.toml</code>.</li><li>Install plugins directly from GitHub repository URLs, and surface each install&#39;s origin and trust level (kimi-official, curated, third-party) in the plugin manager.</li></ul><h3 id="bug-fixes-54" tabindex="-1">Bug Fixes <a class="header-anchor" href="#bug-fixes-54" aria-label="Permalink to &quot;Bug Fixes&quot;">​</a></h3><ul><li>Show the real terminal status of background agents in the transcript so lost, failed, and killed ones no longer appear as completed, and include the resume agent id and recovery instructions in the failure notification so the model can resume reliably.</li><li>Recover from provider model token limit errors during long conversations.</li><li>Automatically retry when a model response stream is dropped mid-flight (a <code>terminated</code> error) instead of failing the turn.</li><li>Handle context overflow errors consistently across provider responses.</li><li>Back off failed compaction retries by a fixed slice of the model context window.</li><li>Fix the native self-updater reporting a successful update when the install command actually failed.</li><li>Project persisted hook and blocked prompt messages into model context.</li><li>Keep blocked prompt hook conversations available to subsequent model turns.</li><li>Fix footer leaking onto the terminal when resuming a non-existent session.</li><li>Fix automatic ripgrep installation when temporary files are on another filesystem.</li></ul><h3 id="polish-46" tabindex="-1">Polish <a class="header-anchor" href="#polish-46" aria-label="Permalink to &quot;Polish&quot;">​</a></h3><ul><li>Remove the default per-turn step limit of 1000. Users can still set <code>max_steps_per_turn</code> in config to enforce a custom limit.</li><li>Support querying sessions by sessionId or workDir in listSessions, and show a helpful cd command when resuming a session from a different working directory.</li><li>Expand the footer&#39;s rotating tips to surface more commands and shortcuts, featuring newer and important ones more prominently.</li><li>Improve the usage information display in the TUI.</li><li>Restrict plugin trust badges to Kimi-hosted plugin CDN URL patterns.</li><li>Clarify subagent and background task stop messages as user-initiated.</li><li>Align the datasource plugin with the generic two-tool workflow.</li></ul><h3 id="refactors-19" tabindex="-1">Refactors <a class="header-anchor" href="#refactors-19" aria-label="Permalink to &quot;Refactors&quot;">​</a></h3><ul><li>Introduce <code>ModelProvider</code> interface and <code>SingleModelProvider</code> to decouple <code>Agent</code> from <code>ProviderManager</code>.</li><li>Split <code>RuntimeConfig</code> into <code>Kaos</code> and <code>ToolServices</code> and update all references accordingly.</li><li>Slim the LLM diagnostic logs with fewer, more compact fields.</li><li>Relocate shared tool service typing to the tool support layer.</li></ul><h2 id="_0-5-0-2026-05-28" tabindex="-1">0.5.0 (2026-05-28) <a class="header-anchor" href="#_0-5-0-2026-05-28" aria-label="Permalink to &quot;0.5.0 (2026-05-28)&quot;">​</a></h2><h3 id="features-35" tabindex="-1">Features <a class="header-anchor" href="#features-35" aria-label="Permalink to &quot;Features&quot;">​</a></h3><ul><li><p>Add scheduled tasks:</p><p>You can now ask the agent to remind you at a specific time, run a task on a recurring cron schedule (for example, check a deploy every 5 minutes or run a daily report every weekday at 9am), or come back on its own in a few minutes to continue what it was doing.</p><p>Schedules use the standard 5-field cron syntax.</p></li><li><p>Add <code>/auto</code> slash command and <code>--auto</code> CLI flag for auto permission mode.</p></li><li><p>Show file content and diff in Write and Edit approval prompts, and open them in a dedicated full-screen viewer on ctrl+e instead of expanding inline.</p></li></ul><h3 id="bug-fixes-55" tabindex="-1">Bug Fixes <a class="header-anchor" href="#bug-fixes-55" aria-label="Permalink to &quot;Bug Fixes&quot;">​</a></h3><ul><li>Fix compaction to handle edge cases where no messages are compactable and improve retry logic.</li><li>Fix official datasource tools to preserve complete responses and write returned result files.</li><li>Fix migration mapping the legacy <code>default_yolo</code> key to the dead <code>yolo</code> field instead of <code>default_permission_mode</code>.</li></ul><h3 id="polish-47" tabindex="-1">Polish <a class="header-anchor" href="#polish-47" aria-label="Permalink to &quot;Polish&quot;">​</a></h3><ul><li>Add a clickable changelog link to the update prompt.</li><li>Show the full Bash command when expanding a Bash tool card with <code>ctrl+o</code>. The header still truncates long commands at 60 chars, but the expanded view now reveals the complete multi-line command above the output.</li><li>Shorten the session title written to the terminal window/tab from 80 to 32 characters so long first messages and pasted content no longer stretch the tab bar past readable width.</li><li>Cap the inline todo panel at five rows and show a <code>+N more</code> indicator so long task lists no longer fill the screen.</li><li>Clarify plugin manager keyboard shortcuts and show plugin state changes inline.</li><li>Report discovered plugin skills in plugin manager summaries.</li><li>Offload large base64 media payloads from <code>wire.jsonl</code> into external blob files to reduce wire size and memory pressure during session replay. Includes an in-memory read-through cache on <code>BlobStore</code> so repeated rehydration avoids redundant disk reads.</li><li>Wrap long question, body, and option text in the AskUserQuestion dialog instead of truncating with an ellipsis. The question prompt, body description, option label, option description, and submit-tab review entries now flow onto multiple lines with a hanging indent.</li></ul><h3 id="refactors-20" tabindex="-1">Refactors <a class="header-anchor" href="#refactors-20" aria-label="Permalink to &quot;Refactors&quot;">​</a></h3><ul><li>Refactor TUI code structure.</li></ul><h2 id="_0-4-0-2026-05-27" tabindex="-1">0.4.0 (2026-05-27) <a class="header-anchor" href="#_0-4-0-2026-05-27" aria-label="Permalink to &quot;0.4.0 (2026-05-27)&quot;">​</a></h2><h3 id="features-36" tabindex="-1">Features <a class="header-anchor" href="#features-36" aria-label="Permalink to &quot;Features&quot;">​</a></h3><ul><li>Add user-global plugin installation, interactive plugin management, plugin-provided skills, and plugin-owned MCP servers.</li><li>Expand folded paste markers on second paste.</li><li>Rework tool permissions: reads outside cwd no longer prompt, session approvals match the exact call, and path-based rules are case-insensitive.</li><li>Add <code>/export-debug-zip</code> slash command to export the current session as a debug ZIP archive directly from the TUI.</li><li>Add <code>/export-md</code> slash command to export the current session as a Markdown file.</li></ul><h3 id="bug-fixes-56" tabindex="-1">Bug Fixes <a class="header-anchor" href="#bug-fixes-56" aria-label="Permalink to &quot;Bug Fixes&quot;">​</a></h3><ul><li>Prevent the TUI from crashing when pull request lookup fails during startup.</li><li>Fix thinking spinner leaking past turn end when an empty thinking delta creates an orphaned thinking component.</li><li>Show the original session resume command after forking a session.</li><li>Restrict plugin zip installs to manifests at the archive root or a single wrapper directory.</li><li>Route session-tagged log entries exclusively to the session sink instead of duplicating them to the global sink. Consistently omit stable main-agent context keys from all session log lines that carry <code>agentId=main</code>.</li></ul><h3 id="refactors-21" tabindex="-1">Refactors <a class="header-anchor" href="#refactors-21" aria-label="Permalink to &quot;Refactors&quot;">​</a></h3><ul><li>Refactor TUI resume replay logic.</li><li>Use one retry classification for transient LLM failures across regular turns and compaction.</li></ul><h3 id="other-1" tabindex="-1">Other <a class="header-anchor" href="#other-1" aria-label="Permalink to &quot;Other&quot;">​</a></h3><ul><li>Enhance <code>kimi export</code> to include more diagnostic information in the manifest.</li></ul><h2 id="_0-3-0-2026-05-26" tabindex="-1">0.3.0 (2026-05-26) <a class="header-anchor" href="#_0-3-0-2026-05-26" aria-label="Permalink to &quot;0.3.0 (2026-05-26)&quot;">​</a></h2><h3 id="features-37" tabindex="-1">Features <a class="header-anchor" href="#features-37" aria-label="Permalink to &quot;Features&quot;">​</a></h3><ul><li><code>/logout</code> now opens a picker so you can choose which provider to log out of, instead of always logging out the one tied to the current model. The current provider is highlighted by default, so pressing Enter matches the previous behavior. The command is also available as <code>/disconnect</code>.</li><li>The <code>openai</code> provider now works out of the box for OpenAI-compatible reasoner models: it auto-detects thinking fields in responses (<code>reasoning_content</code> / <code>reasoning_details</code> / <code>reasoning</code>) and auto-injects <code>reasoning_effort</code> when history contains prior thinking. DeepSeek, Qwen, One API and other gateway-fronted services no longer need a hand-set <code>reasoning_key</code>, which remains available as an explicit override for non-standard gateways.</li></ul><h3 id="bug-fixes-57" tabindex="-1">Bug Fixes <a class="header-anchor" href="#bug-fixes-57" aria-label="Permalink to &quot;Bug Fixes&quot;">​</a></h3><ul><li>Prevent running the <code>/model</code> and <code>/sessions</code> slash commands while streaming or compacting context.</li><li>Preserve catalog-declared interleaved reasoning fields for OpenAI-compatible models configured through <code>/connect</code>.</li><li>Fix API key input dialog showing a masked dot in empty state.</li><li>Fix user skills in <code>~/.agents/</code> not being loaded.</li><li>Restore real-time token display for running subagents in the TUI.</li><li>Hide the todo panel on resume when all todos are already completed.</li><li>Always emit a paired tool result when a tool returns a malformed or missing result, preventing the next request from failing with a missing tool_call_id error.</li><li>Fix Plan mode session resets so new sessions no longer fail after plan review rejection and continue receiving events after setup errors.</li><li>Exit promptly when the controlling terminal goes away. The TUI now handles <code>SIGHUP</code> / <code>SIGTERM</code> and stdout/stderr <code>EIO</code> / <code>EPIPE</code> / <code>ENOTCONN</code> errors, preventing leftover <code>kimi</code> processes that pin a CPU core after the parent shell or multiplexer dies unexpectedly.</li><li>Avoid overly small local completion caps that can truncate reasoning before summaries are produced.</li></ul><h3 id="refactors-22" tabindex="-1">Refactors <a class="header-anchor" href="#refactors-22" aria-label="Permalink to &quot;Refactors&quot;">​</a></h3><ul><li>Make <code>AgentRecords</code> hold the <code>Agent</code> instance directly and inline the restore dispatch logic.</li></ul><h3 id="other-2" tabindex="-1">Other <a class="header-anchor" href="#other-2" aria-label="Permalink to &quot;Other&quot;">​</a></h3><ul><li>Improve the Write tool UX.</li></ul><h2 id="_0-2-0-2026-05-26" tabindex="-1">0.2.0 (2026-05-26) <a class="header-anchor" href="#_0-2-0-2026-05-26" aria-label="Permalink to &quot;0.2.0 (2026-05-26)&quot;">​</a></h2><h3 id="features-38" tabindex="-1">Features <a class="header-anchor" href="#features-38" aria-label="Permalink to &quot;Features&quot;">​</a></h3><ul><li>Add a <code>/connect</code> command that configures a provider and model from a model catalog.</li><li>The <code>/connect</code> provider and model pickers now support type-to-search filtering, and long lists are paginated. The <code>/model</code> picker is also paginated when many models are configured.</li><li>Add <code>Ctrl-J</code> as an additional shortcut for inserting new lines in the TUI prompt.</li><li>Add wire record migration handling during session replay.</li><li>Migrate user skills from <code>~/.kimi/skills/</code> to <code>~/.kimi-code/skills/</code> during the first-launch migration; existing target skills are kept.</li><li>Emit session resume hint as a structured meta message in stream-json output format.</li></ul><h3 id="bug-fixes-58" tabindex="-1">Bug Fixes <a class="header-anchor" href="#bug-fixes-58" aria-label="Permalink to &quot;Bug Fixes&quot;">​</a></h3><ul><li>Report the macOS product version in OAuth device information instead of the Darwin kernel version.</li><li>Correct the <code>X-Msh-Platform</code> header value to <code>kimi_code_cli</code>.</li><li>Clarify the prompt-mode error when no model is configured by pointing users to the login flow.</li><li>Hide the empty current session from the sessions picker while keeping other empty sessions visible.</li><li>Stop mentioning OAuth credentials in the migration UI — they are never migrated, so the previous &quot;needs /login&quot; notice misread as a failure. OAuth-only installs no longer trigger the migration screen.</li><li>Surface API-provided error messages during feedback, usage, login, and model setup failures.</li><li>Persist model selections from the terminal UI to the default configuration, and honor the configured default thinking state for new sessions.</li><li>Retry compaction responses that do not contain a summary before updating conversation history.</li><li>Avoid CPU spikes from large streamed tool arguments and coalesce high-frequency streaming UI updates.</li><li>Resume sessions with a newer wire protocol version instead of failing. A warning is now shown in the TUI and records are replayed without migration.</li><li>Warn tmux users when extended key settings may prevent modified Enter shortcuts from working.</li><li>Let Kimi requests use the remaining context window for completion tokens by default while keeping explicit environment limits as hard caps.</li></ul><h3 id="refactors-23" tabindex="-1">Refactors <a class="header-anchor" href="#refactors-23" aria-label="Permalink to &quot;Refactors&quot;">​</a></h3><ul><li>Flatten tool call data by inlining tool names and arguments at the top level, and limit legacy record migration so it only rewrites matching tool call payloads.</li><li>Move wire metadata handling into the record layer and keep persistence backends limited to storage operations.</li></ul><h3 id="other-3" tabindex="-1">Other <a class="header-anchor" href="#other-3" aria-label="Permalink to &quot;Other&quot;">​</a></h3><ul><li>When no models are configured, <code>/model</code> and the welcome panel now point users to <code>/login</code> (for Kimi) and <code>/connect</code> (for other providers).</li></ul>',411)])])}const p=i(s,[["render",l]]);export{m as __pageData,p as default};
